  'icon-sm': '1rem',    // 16px - Inline text, small buttons, dense UI
  'icon-md': '1.25rem', // 20px - Form inputs, triggers, medium buttons
  'icon-lg': '1.5rem',  // 24px - Navigation, standard buttons (most common)
