// Both schedulers are `setInterval` loops that only ever arm on a persistent
// platform — on Vercel `platform.persistent` is false and they do nothing. Left
// as static imports they still dragged their whole transitive graph
// (@aws-sdk/client-s3, web-push, the AI SDK and all three @ai-sdk providers)
// into Lambda init for EVERY page render. Behind a gated dynamic import Rollup
// splits them into their own chunk, so serverless cold starts never load them.
if (platform.persistent) {
	await import('#lib/server/jobs/scheduler.ts');
	await import('#lib/server/jobs/delivery-scheduler.ts');
}

logAdminConfig();

const ALLOWED_LOCALES = new Set<string>(locales);

/** Upstash rate limiter for auth endpoints */
const authRatelimit = createLimiter('ratelimit:auth', RATE_LIMIT_MAX, RATE_LIMIT_WINDOW);

/**
 * Separate, more generous bucket for OAuth callbacks. A callback GET is a
 * full-page navigation that arrives on top of the sign-in POST, so sharing the
 * strict bucket let a handful of logins dead-end the browser on raw 429 JSON.
 * Callbacks are protected by Better Auth's one-time state validation.
 */
const authCallbackRatelimit = createLimiter('ratelimit:auth-cb', CALLBACK_RATE_LIMIT_MAX, CALLBACK_RATE_LIMIT_WINDOW);

/**
 * Per-ACCOUNT limiter for second-factor verification. The per-IP authRatelimit
 * alone is rotation-bypassable against a 6-digit TOTP space; these paths get a
 * second check keyed on the pending user.
 */
const twoFactorVerifyLimiter = createLimiter(
	'ratelimit:2fa:verify',
	STEPUP_VERIFY_RATE_LIMIT_MAX,
	STEPUP_VERIFY_RATE_LIMIT_WINDOW,
	// Fail CLOSED on Upstash slowness. A 6-digit TOTP is a 10^6 keyspace: an
	// unenforced window here is worth far more to an attacker than the cost of
	// briefly refusing second-factor verification during a Redis blip.
	'closed',
);

const TWO_FACTOR_VERIFY_PATHS = new Set([
	'/api/auth/two-factor/verify-totp',
	'/api/auth/two-factor/verify-backup-code',
	'/api/auth/two-factor/verify-otp',
]);

/**
 * Request timing — outermost, so `total` really is the whole request.
 *
 * It sits ABOVE `securityHeaders` rather than below it because a handler can only
 * measure what it wraps, and the chain itself is a thing worth measuring: the gap
 * between `total` and the spans downstream layers recorded IS the middleware cost.
 * Nothing security-relevant moves as a result — `securityHeaders` still stamps
 * `locals.clientIp` before any limiter or auth handler reads it, which is the
 * invariant its position exists to hold (see handle-chain.gate.test.ts).
 *
 * `Server-Timing` is readable by any client, so the span breakdown is disclosure:
 * it maps internal architecture and hands out a timing oracle. Full detail goes only
 * to callers who already see internals — admins, and devices paired for debugging.
 * Everyone else gets `total`, which tells them what they could measure anyway.
 *
 * Prerendered routes never reach this handler on Vercel: they are served as static
 * files by the CDN. Coverage is dynamic responses, and the docs say so rather than
 * implying otherwise.
 */
const requestTiming: Handle = async ({ event, resolve }) => {
	const timing = startRequestTiming();
	event.locals.timing = timing;

	const response = await resolve(event);

	// Same guard as securityHeaders: a Response.redirect() downstream has IMMUTABLE
	// headers, and instrumentation must never be the thing that 500s a request.
	try {
		const detail = isAdminUserId(event.locals.user?.id) || event.locals.debugOwnerId !== null;
		const header = toServerTimingHeader(timing, { detail });
		// The round-trip count is joined to the spans HERE rather than inside
		// `toServerTimingHeader`, which deliberately knows nothing about the database.
		// This is the one place both request-scoped recorders are in scope, and "620ms,
		// and 47 of them were queries" is the pair an admin is actually reading for.
		// Admin-only, same disclosure rule as the spans themselves.
		const queries = detail && event.locals.queries ? `, db_queries;desc="${event.locals.queries.count}"` : '';
		if (header) response.headers.set('Server-Timing', header + queries);
	} catch {
		// Deliberately silent: an immutable-header response is a normal shape, and a
		// log line per redirect would be the noisiest thing in the chain.
	}

	return response;
};

/**
 * Request budget
 *
 * Stamps `event.locals.deadline` so every downstream operation can ask how much of
 * the request's latency budget is LEFT rather than inventing a timeout of its own.
 * Second in the chain, immediately after timing, because a budget that starts partway
 * through the pipeline is not the request's budget.
 *
 * Stamping it is not enforcing it: nothing downstream is bounded until a leaf actually
 * takes a `child()` and honours it. See `docs/blueprint/velocity/runtime.md` for which
 * leaves have, and which are next.
 */
const requestDeadline: Handle = async ({ event, resolve }) => {
	event.locals.deadline = startDeadline();
	return resolve(event);
};

/**
 * Query census
 *
 * Counts the database round trips this request makes, at any depth. Third, so the
 * count includes the session lookup — auth is where a per-request query surprise is
 * most likely and least visible.
 *
 * The count is a TRIPWIRE, not a budget: the ceiling is generous and exists to make
 * the request that suddenly issues ninety queries say so, instead of surfacing weeks
 * later as a database bill. Per-operation budgets are asserted where they can be
 * proved — `src/lib/server/db/query-budget.gate.pglite.test.ts` runs each registered
 * operation over two data sizes, which is the only place N+1 is provable rather than
 * suspected.
 */
const queryCensus: Handle = async ({ event, resolve }) => {
	const census = startQueryCensus();
	event.locals.queries = census;

	const response = await census.run(() => resolve(event));

	if (census.count > REQUEST_QUERY_CEILING) {
		const worst = census.worst();
		console.warn(
			`[query-census] ${event.request.method} ${event.url.pathname} made ${census.count} queries ` +
				`(ceiling ${REQUEST_QUERY_CEILING})` +
				(worst ? `; most repeated shape ×${worst.times}: ${worst.shape}` : ''),
		);
	}

	return response;
};

/**
 * Security headers + canonical client IP stamp
 *
 * Stamps event.locals.clientIp and x-client-ip ONCE here, before any other
 * handler. Downstream code MUST read event.locals.clientIp (or x-client-ip
 * which Better Auth's ipAddressHeaders is pinned to) rather than re-deriving
 * from request headers — those are attacker-mutable until this handler runs.
 */
export const securityHeaders: Handle = async ({ event, resolve }) => {
	if (!building) {
		const ip = event.getClientAddress();
		event.locals.clientIp = ip;
		event.request.headers.set('x-client-ip', ip);
	} else {
		event.locals.clientIp = null;
	}

	const response = await resolve(event);

	// Guarded: a `Response.redirect()` anywhere downstream has IMMUTABLE headers
	// and would turn every request into a 500 here. None exists today, but the
	// first one added must degrade to "no extra headers on that redirect", not
	// take down the whole chain. (docs/system-abstraction.md documents this.)
	try {
		response.headers.set('X-Frame-Options', 'DENY');
		response.headers.set('X-Content-Type-Options', 'nosniff');
		response.headers.set('Referrer-Policy', 'strict-origin-when-cross-origin');
		response.headers.set('Permissions-Policy', 'camera=(), microphone=(), geolocation=()');
		response.headers.set('Strict-Transport-Security', `max-age=${HSTS_MAX_AGE}; includeSubDomains; preload`);
		// Cross-origin isolation (Spectre-class). same-origin-allow-popups keeps redirect/popup
		// OAuth flows working. COEP is intentionally NOT set (would require a CORP audit of
		// R2 / Carto / font origins). CORP same-site blocks cross-site resource hot-linking.
		response.headers.set('Cross-Origin-Opener-Policy', 'same-origin-allow-popups');
		response.headers.set('Cross-Origin-Resource-Policy', 'same-site');
		response.headers.set('X-DNS-Prefetch-Control', 'off');

		// Never cache user-specific or API responses on shared/intermediary caches.
		// The !has() guard preserves explicit Cache-Control set by a load/endpoint
		// (e.g. the data page's no-store, the blog-image proxy's public max-age).
		const isApi = event.url.pathname.startsWith('/api/');
		if ((event.locals.user || isApi) && !response.headers.has('Cache-Control')) {
			response.headers.set('Cache-Control', 'no-store, private');
		}

		// On logout, instruct the browser to purge cached pages, cookies, and storage
		// so a back-button after sign-out cannot reveal the prior session's data.
		if (event.url.pathname === '/api/auth/sign-out' && response.status >= 200 && response.status < 300) {
			response.headers.set('Clear-Site-Data', '"cache", "cookies", "storage"');
		}
	} catch (err) {
		console.error('[securityHeaders] immutable response headers — skipped:', err instanceof Error ? err.message : err);
	}

	return response;
};

/**
 * Request-body floor
 *
 * Refuses a mutating request that DECLARES more than MAX_REQUEST_BYTES, before
 * anything downstream reads the body.
 *
 * This is advisory, and saying so is the point. `Content-Length` is absent
 * under chunked transfer encoding and optional in HTTP/2, so a one-line client
 * change walks past it. Its value is that it is free, it covers every route
 * including the 60-odd form actions no per-route control will ever reach, and
 * it replaces Vercel's opaque platform 413 with our own error shape. The
 * enforceable control is `readJsonBounded`/`readTextBounded` at the endpoints
 * that actually matter; this must never become the reason one of them skips it.
 *
 * Position is load-bearing on both sides. It sits after `securityHeaders`,
 * which stamps headers on the way back out, so a 413 still leaves with them.
 * It sits before `authHandler`, because Better Auth's `svelteKitHandler`
 * terminates and consumes the body for `/api/auth/*` — below it, sign-up
 * payloads would stay unbounded.
 */
const bodySizeFloor: Handle = async ({ event, resolve }) => {
	const method = event.request.method;
	if (method === 'POST' || method === 'PUT' || method === 'PATCH' || method === 'DELETE') {
		const declared = Number(event.request.headers.get('content-length'));
		if (Number.isFinite(declared) && declared > MAX_REQUEST_BYTES) {
			return payloadTooLargeResponse(MAX_REQUEST_BYTES);
		}
	}
	return resolve(event);
};

/**
 * loadStyle — reads/generates style from cookie, populates event.locals.style
 *
 * The cookie write is decided before resolve (SvelteKit refuses `cookies.set` after it)
 * but kept only on responses that render the app shell — see `scopeStyleCookie`. A
 * cookieless crawler fetching `/sitemap.xml` used to get a fresh random style on every
 * hit, and that `Set-Cookie` made the endpoint's `s-maxage` uncacheable on Vercel.
 */
const loadStyle: Handle = async ({ event, resolve }) => {
	// locals.style is consumed only by HTML rendering. Skip the cookie parse + custom
	// palette lookup on API routes (never render HTML) and SSR subrequests (internal
	// fetches that don't produce the app shell) — saves work on every such request.
	if (event.url.pathname.startsWith('/api/') || event.isSubRequest) {
		return resolve(event);
	}

	const cookieValue = event.cookies.get(STYLE_COOKIE_NAME);
	let config = parseStyleCookie(cookieValue);
	let resolved: ResolvedStyle | null = null;

	// Resolve: CP_ path (async DB lookup) vs registry path (sync)
	if (config?.paletteId?.startsWith('CP_')) {
		try {
			const cp = await getCustomPaletteById(config.paletteId);
			if (cp) {
				const typography = getTypography(config.typographyId);
				const radius = getRadius(config.radiusId);
				if (typography && radius) {
					resolved = {
						paletteId: config.paletteId as PaletteId,
						typographyId: config.typographyId,
						radiusId: config.radiusId,
						paletteName: cp.name,
						typographyName: typography.name,
						radiusName: radius.name,
					};
					event.locals.customPaletteColors = {
						light: cp.lightColors as Record<string, string>,
						dark: cp.darkColors as Record<string, string>,
					};
					event.locals.customPaletteAccentOffset = cp.accentOffset ?? 0;
				}
			}
		} catch {
			// Custom palette not found or DB error — fall through to random
		}
	} else if (config) {
		resolved = resolveStyle(config);
	}

	// Fallback: no valid resolution → random
	if (!resolved) {
		config = generateRandomStyle();
		const fallback = resolveStyle(config);
		if (!fallback) throw new Error('Failed to resolve random style');
		resolved = fallback;
	}

	if (!config) throw new Error('Style config missing after resolution');
	const serialized = serializeStyleCookie(config);
	if (cookieValue !== serialized) {
		event.cookies.set(STYLE_COOKIE_NAME, serialized, STYLE_COOKIE_OPTIONS);
	}

	event.locals.style = resolved;
	const response = await resolve(event);
	scopeStyleCookie(response, event.isDataRequest);
	return response;
};

/**
 * Strip leading /en/ — base locale must not be URL-prefixed.
 *
 * Paraglide's URL pattern serves the base locale at unprefixed paths.
 * /en/foo has no canonical place to live; redirect to /foo (308 = permanent,
 * preserves method) so typed/shared URLs land on the canonical form and
 * search engines don't see duplicates.
 *
 * Scoped to startsWith('/en/') only — `/en` (no trailing slash) is preserved
 * because it currently matches a real SvelteKit route (separate concern).
 */
const stripBaseLocalePrefix: Handle = ({ event, resolve }) => {
	// Read only pathname up front. Destructuring `search`/`hash` here would
	// eagerly invoke those getters, and SvelteKit throws on `url.search`
	// during prerendering — crashing every prerendered page before the
	// /en/ check runs. Prerendered pages are never /en/-prefixed, so the
	// guarded access below is never reached at build time.
	const { pathname } = event.url;
	if (pathname.startsWith('/en/')) {
		// `slice(3)` alone is an open redirect: /en//evil.com yields the
		// protocol-relative //evil.com, which this handler would then emit as a
		// 308 — permanent, browser-cached, and upstream of every auth, CSRF and
		// rate-limit handler in the chain. Validate before building Location.
		const safe = sanitizeInternalPath(pathname.slice(3) + event.url.search);
		if (safe) {
			return new Response(null, { status: 308, headers: { Location: safe } });
		}
		// Attacker-shaped path: decline to redirect rather than invent a target.
		// A 308 to a manufactured fallback would durably bind that nonsense path
		// to the fallback in caches and crawlers. Falling through 404s instead.
	}
	return resolve(event);
};

/**
 * i18n — Paraglide locale detection + HTML lang attribute + style attrs
 *
 * Stamps event.locals.locale (canonical adapter handoff so domain code never
 * imports from #lib/paraglide). Persists URL-resolved locale to the
 * PARAGLIDE_LOCALE cookie when it diverges, so later non-prefixed requests
 * resolve consistently (Paraglide v2 does not auto-write on URL resolution).
 */
const i18n: Handle = ({ event, resolve }) =>
	paraglideMiddleware(event.request, ({ locale }) => {
		const safeLocale = (ALLOWED_LOCALES.has(locale) ? locale : 'en') as App.Locals['locale'];
		event.locals.locale = safeLocale;
		// Skip Set-Cookie when the resolved locale equals baseLocale AND no cookie
		// is present yet — avoids polluting CDN-cacheable responses for first-visit
		// anonymous users on the default locale.
		const existingCookie = event.cookies.get(PARAGLIDE_LOCALE_COOKIE);
		const isDefaultFirstVisit = existingCookie === undefined && safeLocale === 'en';
		if (!isDefaultFirstVisit && existingCookie !== safeLocale) {
			event.cookies.set(PARAGLIDE_LOCALE_COOKIE, safeLocale, {
				path: '/',
				httpOnly: false,
				secure: typeof process !== 'undefined' ? process.env.NODE_ENV === 'production' : true,
				sameSite: 'lax',
				maxAge: cookieMaxAge,
			});
		}
		// The callback's `request` carries the de-localized URL (`/de/blog` → `/blog`), which only
		// matters to apps that route on it. Locale is a route segment here (`[[locale=locale]]`), so
		// routing has already matched, and `event.request` (read-only since SvelteKit 3) keeps the
		// URL the client sent. Nothing downstream reads its path; the MCP adapter reads its origin.

		// All per-response derivations stay OUT of the per-chunk callback: computing
		// the custom-palette <style> block there (two culori-backed
		// deriveAccentTokens calls) would rerun it on every HTML chunk. Computed
		// once here, injected only when the </head> marker passes.
		const style = event.locals.style;
		const paletteId = style?.paletteId ?? '';
		const typographyId = style?.typographyId ?? '';
		const radiusId = style?.radiusId ?? '';

		let customPaletteStyle = '';
		const cp = event.locals.customPaletteColors;
		if (cp && paletteId) {
			const accentOffset = event.locals.customPaletteAccentOffset ?? 0;
			const lightAccent = cp.light.primary ? deriveAccentTokens(cp.light.primary, accentOffset) : {};
			const darkAccent = cp.dark.primary ? deriveAccentTokens(cp.dark.primary, accentOffset) : {};

			const lightExplicit = new Set(safeEntries(cp.light).map(([k]) => k));
			const darkExplicit = new Set(safeEntries(cp.dark).map(([k]) => k));

			const lightVars = [
				...safeEntries(cp.light),
				...Object.entries(lightAccent).filter(([k]) => !lightExplicit.has(k)),
			]
				.map(([k, v]) => `${tokenToCssVar(k)}:${v}`)
				.join(';');
			const darkVars = [...safeEntries(cp.dark), ...Object.entries(darkAccent).filter(([k]) => !darkExplicit.has(k))]
				.map(([k, v]) => `${tokenToCssVar(k)}:${v}`)
				.join(';');
			const safePid = paletteId.replace(/[^a-zA-Z0-9_-]/g, '');
			customPaletteStyle = `<style>[data-palette="${safePid}"]{${lightVars}}.dark[data-palette="${safePid}"]{${darkVars}}</style>`;
		}

		// Fonts are deliberately NOT preloaded (Kit's default preloads scripts and styles
		// only). Measured 2026-10-10, lab, Slow 4G + 4× CPU, n=5: preloading the visitor's
		// heading + body faces delayed FCP by 60–120 ms on every page tested and added
		// ~110 ms TBT on the home page, while its LCP effect did not reproduce between
		// runs. The metric-matched fallback faces (font-fallbacks.css) carry the swap.
		return resolve(event, {
			transformPageChunk: ({ html }) => {
				let result = html
					.replace('%lang%', safeLocale)
					.replace('%palette%', paletteId)
					.replace('%typography%', typographyId)
					.replace('%radius%', radiusId);
				if (customPaletteStyle && result.includes('</head>')) {
					result = result.replace('</head>', `${customPaletteStyle}</head>`);
				}
				return result;
			},
		});
	});

/**
 * Auth captcha gate — verify ALTCHA token before email-sending auth routes.
 *     Token is sent via x-altcha-token header by the client (Better Auth
 *     fetchOptions.headers). We MUST verify here, not in form actions, because
 *     the Better Auth client posts JSON directly to /api/auth/* and form-action
 *     wrapping is not in the path.
 */
const AUTH_CAPTCHA_GATED_PATHS = new Set([
	'/api/auth/sign-in/magic-link',
	'/api/auth/email-otp/send-verification-otp',
	'/api/auth/two-factor/send-otp', // sends email — same abuse surface (body has no email; ALTCHA check still applies)
]);

const authCaptchaGate: Handle = async ({ event, resolve }) => {
	if (building) return resolve(event);
	if (event.request.method !== 'POST') return resolve(event);
	if (!AUTH_CAPTCHA_GATED_PATHS.has(event.url.pathname)) return resolve(event);

	const ctx = { route: event.url.pathname, clientIp: event.locals.clientIp };

	const captchaDecision = await verifyAltcha(event.request.headers.get('x-altcha-token'));
	if (!captchaDecision.allowed) {
		logBlocked(captchaDecision, ctx);
		return authDecisionResponse(captchaDecision);
	}

	// Read email from a clone so Better Auth can still consume the body.
	let email: string | null = null;
	try {
		const body = await event.request.clone().json();
		if (typeof body?.email === 'string') email = body.email;
	} catch {
		// Malformed body — Better Auth will reject; nothing to enforce here.
	}

	if (email) {
		const emailDecision = await checkEmailRateLimit(email);
		if (!emailDecision.allowed) {
			logBlocked(emailDecision, ctx);
			return authDecisionResponse(emailDecision);
		}
	}

	const response = await resolve(event);
	// Consume a per-email slot only for sends Better Auth accepted — denied and
	// failed attempts must not eat quota, or retrying while limited would keep
	// the sliding window full and extend the lockout indefinitely.
	if (email && response.ok) await recordEmailSend(email);

	// Make the outcome uniform across "we won't do this" failures.
	//
	// The quota rule above is correct and stays — counting failed probes would
	// re-introduce the lockout DoS it exists to prevent. But it does mean a probe
	// for a non-existent address is CHEAP, so the thing that must not differ is
	// the observable response. A 4xx here encodes a refusal, and "refused"
	// includes "no such account" — which an unauthenticated caller does not get
	// to learn.
	//
	// Two statuses pass through deliberately:
	//  - 429, which is about the CALLER's rate, not the target's existence, and
	//    which the client needs in order to back off.
	//  - 5xx, which means the send genuinely broke. Masking that would tell the
	//    user "check your email" during a provider outage and hide the failure.
	if (response.status >= 400 && response.status < 500 && response.status !== 429) {
		return authAmbiguousResponse();
	}
	return response;
};

/**
 * The single response every refused email-send returns, so "no such account"
 * and "address rejected" are indistinguishable from a successful send.
 *
 * Mirrors the success body Better Auth returns for these endpoints, so a client
 * cannot separate the two by shape either.
 */
function authAmbiguousResponse(): Response {
	return new Response(JSON.stringify({ status: true }), {
		status: 200,
		headers: { 'Content-Type': 'application/json' },
	});
}

/**
 * 429 for /api/auth/*: JSON for fetch clients, but a full-page navigation
 * (OAuth callback GET, magic-link verify GET) must never render raw JSON —
 * redirect to the localized login page with a readable error instead.
 */
function authRateLimited(event: RequestEvent, reset: number, message: string): Response {
	if (isDocumentRequest(event.request.headers)) {
		const login = localizeHref('/auth/login', { locale: event.locals.locale ?? 'en' });
		return new Response(null, { status: 303, headers: { Location: `${login}?error=rate_limited` } });
	}
	return authDecisionResponse(denied('rate-limit', message, 429, Math.max(0, reset - Date.now())));
}

/**
 * Auth API handler — intercepts /api/auth/* routes
 *    Includes Upstash rate limiting on all auth endpoints
 */
const authHandler: Handle = async ({ event, resolve }) => {
	// During prerender there is no client. Skip rate-limit. clientIp is null.
	if (building) {
		return svelteKitHandler({ event, resolve, auth, building });
	}

	const path = event.url.pathname;

	// Rate limit all auth endpoints (sign-in, sign-out, get-session); OAuth
	// callbacks get their own bucket so retried logins can't starve the flow.
	if (path.startsWith('/api/auth/') && event.locals.clientIp) {
		const limiter = path.startsWith('/api/auth/callback/') ? authCallbackRatelimit : authRatelimit;
		// Bucket on the normalized key, never the raw address: an IPv6 client
		// rotating inside its own /64 would otherwise get 2^64 free buckets.
		const { success, reset } = await limiter.limit(normalizeIpKey(event.locals.clientIp) ?? event.locals.clientIp);

		if (!success) {
			return authRateLimited(event, reset, 'Too many requests. Please try again later.');
		}
	}

	// Second-factor verify endpoints additionally rate-limit per ACCOUNT.
	// sessionPopulate runs after this handler (auth requests terminate here),
	// so the session is resolved inline for these rare paths only.
	if (TWO_FACTOR_VERIFY_PATHS.has(path)) {
		const sessionData = await auth.api.getSession({ headers: event.request.headers }).catch(() => null);
		// Normalize the IP fallback too: without a resolvable session this bucket
		// is the only thing standing between a rotating client and a 6-digit TOTP.
		const limitKey = twoFactorVerifyLimitKey(sessionData?.user.id, normalizeIpKey(event.locals.clientIp));
		const { success, reset } = await twoFactorVerifyLimiter.limit(limitKey);

		if (!success) {
			return authRateLimited(event, reset, 'Too many verification attempts. Please wait before trying again.');
		}
	}

	// x-client-ip and Better Auth's ipAddressHeaders pinning happens in securityHeaders + auth config.

	return svelteKitHandler({ event, resolve, auth, building });
};

/**
 * Session populate — reads session from cookie/headers into event.locals
 *    CRITICAL: svelteKitHandler does NOT populate event.locals (Issue #2188)
 */
const sessionPopulate: Handle = async ({ event, resolve }) => {
	const cookies = event.request.headers.get('cookie');
	if (!cookies?.includes('better-auth.session_token')) {
		event.locals.user = null;
		event.locals.session = null;
		event.locals.grants = [];
		return resolve(event);
	}

	// A Neon outage must not 500 every page that carries a session cookie while
	// anonymous visitors browse fine. Degrade this request to anonymous instead:
	// privileges only ever drop, never widen. (Same .catch precedent as the 2FA
	// path in authHandler.)
	//
	// `readRequestSession` forwards the cookies the read writes. Without that, a cache miss
	// re-issued the `session_data` cookie into a discarded header bag, so after the first
	// five minutes every signed-in request paid the Postgres session lookup again.
	const sessionData = await event.locals.timing.span('auth', () =>
		readRequestSession(event).catch((err) => {
			console.error(
				'[auth] getSession failed — degrading request to anonymous:',
				err instanceof Error ? err.message : err,
			);
			return null;
		}),
	);

	event.locals.user = sessionData?.user ?? null;
	event.locals.session = sessionData?.session ?? null;

	// Ban + revocation are checked here, not left to the session lookup, because
	// `cookieCache` answers getSession() from a signed cookie without touching
	// Postgres for up to SESSION_COOKIE_MAX_AGE. Deleting session rows — what a
	// ban and `revokeSiblings` both do — would otherwise not bite for 5 minutes.
	// `banned` short-circuits only for BANNED users — `false || await …` still awaits.
	// (An earlier comment here claimed the common case skipped Redis; it never did.)
	// So every authenticated request paid an Upstash round trip, and the grant lookup
	// was then awaited serially after it despite being completely independent. Both
	// now run concurrently, and a banned user still costs no Redis call at all.
	const su = event.locals.user;
	const ss = event.locals.session;
	const needsGrants = !!su && readsGrants(event.url.pathname);

	const [revoked, grants] = await Promise.all([
		su && ss ? (su.banned ? Promise.resolve(true) : isSessionRevoked(su.id, ss.createdAt, ss.token)) : false,
		// Skipped wherever nothing reads the result — see readsGrants. Keeping it a plain
		// array avoids an async cascade across ~25 guard call sites.
		needsGrants && su
			? listActiveGrantKinds(su.id).catch((err) => {
					console.error(
						'[auth] grant lookup failed — treating as no grants:',
						err instanceof Error ? err.message : err,
					);
					return [] as Awaited<ReturnType<typeof listActiveGrantKinds>>;
				})
			: Promise.resolve([] as Awaited<ReturnType<typeof listActiveGrantKinds>>),
	]);

	if (revoked) {
		event.locals.user = null;
		event.locals.session = null;
		event.locals.grants = [];
		return resolve(event);
	}

	event.locals.grants = grants;

	return resolve(event);
};

/**
 * CSRF protection — defense in depth on mutating API calls. Predicates
 *    (needsCsrf / isSameHost / exempt set) live in #lib/server/security/csrf
 *    where they are unit-tested; this handler just wires them.
 *
 *    Both rejections answer `{ error: { code, message } }` like every other
 *    door, so a client parsing `body.error.code` works on the path most likely
 *    to fire during integration.
 */
const csrfProtection: Handle = async ({ event, resolve }) => {
	if (needsCsrf(event.request.method, event.url.pathname)) {
		if (!event.request.headers.get('x-requested-with')) {
			return apiError(403, 'csrf_failed', 'Request rejected.');
		}

		const origin = event.request.headers.get('origin');
		const referer = event.request.headers.get('referer');
		const expectedHost = event.url.host;

		// Origin is the authoritative signal when present. Fall back to Referer for
		// clients that omit Origin on same-origin POSTs. If both are missing, reject.
		const ok = origin ? isSameHost(origin, expectedHost) : isSameHost(referer, expectedHost);
		if (!ok) {
			return apiError(403, 'csrf_failed', 'Request rejected.');
		}
	}

	return resolve(event);
};

/**
 * Consent loader — populate event.locals.consentTier from cookie. Defaults to
 *     'necessary'. Lives before routeGuard so admin pages also have a consistent value.
 */
const consentLoader: Handle = async ({ event, resolve }) => {
	event.locals.consentTier = parseConsentTier(event.cookies.get(CONSENT_COOKIE));
	return resolve(event);
};

/**
 * Debug-owner loader — verifies the v10r_debug_owner HMAC cookie and stamps
 *     locals.debugOwnerId so the analyticsCollector can attribute events to the
 *     paired admin. Independent of Better Auth — the phone is not logged in.
 */
const debugOwnerLoader: Handle = async ({ event, resolve }) => {
	const raw = event.cookies.get(PAIRING_COOKIE);
	if (!raw) {
		event.locals.debugOwnerId = null;
		return resolve(event);
	}
	try {
		// verifyOwnerCookie owns the expiry check — a ticket past its `expiresAt` is not `ok`.
		const verified = verifyOwnerCookie(raw);
		if (verified) {
			event.locals.debugOwnerId = verified.adminUserId;
		} else {
			event.locals.debugOwnerId = null;
			clearOwnerCookie(event.cookies);
		}
	} catch {
		// Key material unavailable or other crypto failure — fail closed, don't crash.
		// deriveSubkey only throws when BETTER_AUTH_SECRET is also missing, which cannot
		// happen in a served request; this stays as the backstop for that impossibility.
		event.locals.debugOwnerId = null;
	}
	return resolve(event);
};

/**
 * Dev route guard — hide (dev) routes outside dev.
 * Member and admin auth gates live in app/+layout.server.ts and admin/+layout.server.ts.
 */
const devRouteGuard: Handle = async ({ event, resolve }) => {
	if (!import.meta.env.DEV && event.route.id?.includes('/(dev)/')) {
		error(404, 'Not Found');
	}
	return resolve(event);
};

export const handle = sequence(
	requestTiming,
	requestDeadline,
	queryCensus,
	securityHeaders,
	bodySizeFloor,
	stripBaseLocalePrefix,
	docsMarkdown,
	loadStyle,
	i18n,
	authCaptchaGate,
	authHandler,
	csrfProtection,
	sessionPopulate,
	consentLoader,
	debugOwnerLoader,
	devRouteGuard,
	analyticsCollector,
);

export const handleError = reportServerError;

