		{ id: 'ghost', a: ref('b-1', 'east'), b: ref('nobody', 'west'), mode: 'conduit' },
		{ id: 'pipe', a: ref('b-1', 'east'), b: ref('b-2', 'west'), mode: 'conduit' },
		{ id: 'pipe-again', a: ref('b-2', 'west'), b: ref('b-1', 'east'), mode: 'conduit' },
