		{ id: 'hub-1', a: ref('b-3', 'hub'), b: ref('b-1', 'west'), mode: 'conduit' },
		{ id: 'hub-2', a: ref('b-3', 'hub'), b: ref('b-2', 'hub'), mode: 'conduit' },
	],
	conduits: [
