/**
 * loadProjectMap — the corpus map is cut to the prompt budget, and the map body's own
 * ordering (intro + stack line first) survives that cut on a production-sized map.
 */
import { describe, expect, it, vi } from 'vitest';
import { buildOverviewBody, type OverviewDocFile } from '#lib/server/docs/overview-body.ts';
import { PROJECT_MAP_MAX_CHARS } from '../config';

const getCorpusMap = vi.fn();
vi.mock('#lib/server/db/retrieval/queries.ts', () => ({
	getCorpusMap: (...args: unknown[]) => getCorpusMap(...args),
}));

const { loadProjectMap } = await import('./project-map');

const mapRow = (body: string) => ({ id: 'map_docs', title: 'Map', body, builtAt: new Date() });

describe('loadProjectMap', () => {
	it('returns null when the corpus has no map', async () => {
		getCorpusMap.mockResolvedValueOnce(null);
		expect(await loadProjectMap()).toBeNull();
	});

	it('returns the body whole when under budget', async () => {
		getCorpusMap.mockResolvedValueOnce(mapRow('short body'));
		const map = await loadProjectMap();
		expect(map?.body).toBe('short body');
		expect(map?.truncatedAt).toBeNull();
	});

	it('cuts at the budget with an ellipsis and records where', async () => {
		getCorpusMap.mockResolvedValueOnce(mapRow('a'.repeat(PROJECT_MAP_MAX_CHARS + 500)));
		const map = await loadProjectMap();
		expect(map?.body.length).toBe(PROJECT_MAP_MAX_CHARS + 1); // sliced chars + ellipsis
		expect(map?.body.endsWith('…')).toBe(true);
		expect(map?.truncatedAt).toBe(PROJECT_MAP_MAX_CHARS);
	});

	it('does not cut at exactly the budget', async () => {
		getCorpusMap.mockResolvedValueOnce(mapRow('a'.repeat(PROJECT_MAP_MAX_CHARS)));
		const map = await loadProjectMap();
		expect(map?.body.endsWith('…')).toBe(false);
		expect(map?.truncatedAt).toBeNull();
	});

	// End-to-end with the real map body: an over-budget map (huge blueprint TOC) must still
	// expose the stack summary after the cut — the grounding fix for "which stack does v10r use?".
	it('preserves the Stack line through the cut of a production-sized map', async () => {
		const files: OverviewDocFile[] = [
			...Array.from({ length: 60 }, (_, i) => ({
				sourcePath: `docs/blueprint/area/topic-${i}.md`,
				docsPath: `/docs/blueprint/area/topic-${i}`,
				title: `Blueprint topic number ${i} with a deliberately long padding title to fill space`,
			})),
			{ sourcePath: 'docs/stack/core/bun.md', docsPath: '/docs/stack/bun', title: 'Bun' },
			{ sourcePath: 'docs/stack/core/sveltekit.md', docsPath: '/docs/stack/sveltekit', title: 'SvelteKit' },
			{ sourcePath: 'docs/stack/data/drizzle.md', docsPath: '/docs/stack/drizzle', title: 'Drizzle' },
		];
		const body = buildOverviewBody(files);
		expect(body.length).toBeGreaterThan(PROJECT_MAP_MAX_CHARS); // genuinely over budget → the cut engages

		getCorpusMap.mockResolvedValueOnce(mapRow(body));
		const map = await loadProjectMap();
		expect(map?.body.endsWith('…')).toBe(true);
		expect(map?.body).toContain('**Stack:** Bun · Drizzle · SvelteKit');
	});
});

/**
 * project-map — the corpus map of the project docs, injected on every chatbot turn.
 *
 * The one `retrieval.corpus_map` row `scripts/db/ingest-docs.ts` writes for the system
 * corpus: the model's (and the inspector's) representation of what the documentation covers
 * without loading it — a DB read that grounds broad questions ("what is v10r?") with the
 * embedding quota exhausted. Static per locale, so it sits in the cache-stable prefix.
 */
import { getCorpusMap } from '#lib/server/db/retrieval/queries.ts';
import { PROJECT_DOCS_COLLECTION_ID, SYSTEM_DOCS_USER_ID } from '#lib/server/retrieval/config.ts';
import { PROJECT_MAP_MAX_CHARS } from '../config';
import type { AssistantCapability } from '../profile/profile';

/** The map as loaded for a prompt, and where the budget cut its body (null = whole). */
export interface LoadedProjectMap {
	id: string;
	title: string;
	body: string;
	truncatedAt: number | null;
}

/** Load the project docs corpus map, cut to the prompt budget; null when no map exists. */
export async function loadProjectMap(): Promise<LoadedProjectMap | null> {
	const map = await getCorpusMap([SYSTEM_DOCS_USER_ID], PROJECT_DOCS_COLLECTION_ID);
	if (!map) return null;
	if (map.body.length > PROJECT_MAP_MAX_CHARS) {
		return {
			id: map.id,
			title: map.title,
			body: `${map.body.slice(0, PROJECT_MAP_MAX_CHARS)}…`,
			truncatedAt: PROJECT_MAP_MAX_CHARS,
		};
	}
	return { id: map.id, title: map.title, body: map.body, truncatedAt: null };
}

export const projectMap: AssistantCapability = {
	id: 'project-map',
	when: 'always — the system corpus has a map',
	guidance:
		'A <project-overview> block is the canonical high-level map of v10r (a full-stack reference & test-sandbox). Use it to orient broad questions like "what is v10r" or "how do I use it"; ground specifics from the retrieved documentation and the catalog.',
	sources: ['project-map'],
	activates: () => ({ active: true }),
	grounding: async () => {
		const map = await loadProjectMap();
		if (!map) {
			return {
				source: { id: 'project-map', ran: false, skippedReason: 'empty_corpus', items: [] },
				blocks: [],
				activation: { active: false, reason: 'empty_corpus' },
			};
		}
		return {
			source: {
				id: 'project-map',
				ran: true,
				items: [
					{
						id: map.id,
						kind: 'map',
						title: map.title,
						rank: 0,
						state: 'included',
						chars: map.body.length,
						blockId: 'project-overview',
					},
				],
				...(map.truncatedAt !== null ? { truncatedAt: map.truncatedAt } : {}),
			},
			blocks: [
				{
					id: 'project-overview',
					section: 'grounding',
					text: `<project-overview>\n${map.title}\n\n${map.body}\n</project-overview>`,
					stable: true,
				},
			],
		};
	},
};

