describe('orchestrateChat', () => {
	const baseInput = {
		userId: 'user-1',
		surface: 'deskbot' as const,
		registry,
		messages: [{ id: 'm1', role: 'user' as const, parts: [{ type: 'text' as const, text: 'Hello' }] }],
