/**
 * Chat orchestration — domain module.
 * Handles conversation management, retrieval integration, streaming, and fallback rotation.
 * No SvelteKit imports — reusable from AI tools, REST, and background jobs.
 */

import {
	convertToModelMessages,
	createUIMessageStream,
	createUIMessageStreamResponse,
	type LanguageModel,
	type LanguageModelUsage,
	stepCountIs,
	streamText,
	type UIMessage,
} from 'ai';
import type { HarnessMetadata } from '#lib/components/composites/chatbot/harness-types.ts';
import type { Locale } from '#lib/i18n/index.ts';
import { chargeTokens } from '#lib/server/ai/budget.ts';
import { CHATBOT_GENERATION_OPTIONS, MAX_TOKENS } from '#lib/server/ai/config.ts';
