		expect(pass({ kind: 'cites', path: '/docs/blueprint/security' }, chatbotGrounded)).toBe(true);
		expect(pass({ kind: 'outcome', is: 'ok' }, chatbotGrounded)).toBe(true);
		expect(pass({ kind: 'no-citations' }, chatbotGrounded)).toBe(false);
