/**
 * CORPUS_MAP — the deterministic map of one collection's corpus: what it covers, built at
 * ingest from the documents themselves, never by a model.
 *
 * One row per collection. The chatbot injects the system docs corpus's map on every turn
 * (`<project-overview>`, the `project-map` capability) so the model can orient a broad
 * question without loading the corpus — a plain row read that works with the embedding
 * quota exhausted. `scripts/db/ingest-docs.ts` is its writer.
 */

import { index, text, timestamp, uniqueIndex } from 'drizzle-orm/pg-core';
import { user } from '../auth/_better-auth';
import { collection } from './collection';
import { retrievalSchema } from './embedding-model';

export const corpusMap = retrievalSchema.table(
	'corpus_map',
	{
		id: text('id').primaryKey(),
		// Denormalized from the collection, like `chunk.user_id`: every retrieval read filters
		// on one owner column.
		userId: text('user_id')
			.notNull()
			.references(() => user.id, { onDelete: 'cascade' }),
		collectionId: text('collection_id')
			.notNull()
			.references(() => collection.id, { onDelete: 'cascade' }),
		title: text('title').notNull(),
		body: text('body').notNull(),
		builtAt: timestamp('built_at', { withTimezone: true }).notNull().defaultNow(),
	},
	(t) => [uniqueIndex('corpus_map_collection_uq').on(t.collectionId), index('corpus_map_user_idx').on(t.userId)],
);

files.src/lib/server/dbops/operations.pglite.t:
/**
 * dbops core — invariants a browser test can't safely prove (they'd need a second
 * destructive reset or a concurrency race):
 *   1. the active-unique index actually blocks a 2nd in-flight refresh → ConflictError
 *   2. a terminal operation frees the lock so the next refresh can start
 *   3. idempotency replay returns the original operation without re-firing the Neon restore
 *   4. advanceOperation is idempotent — running → terminal happens exactly once
 *   5. the trimmed PublicBranchOperation never carries raw branch / op ids (Finding A regression)
 *
 * Runs against a real PGlite database — the partial-unique index IS the unit under
 * test — with the Neon Management API mocked at the `#lib/server/neon/index.ts` boundary.
 */
import type { PGlite } from '@electric-sql/pglite';
import { afterAll, beforeEach, describe, expect, it, vi } from 'vitest';

let testClient: PGlite;

// Neon domain — driven per-test; core.ts imports exactly these names.
const neonConfigured = vi.fn(() => true);
const resolveTargets = vi.fn(async () => ({ devBranchId: 'br-dev', parentBranchId: 'br-prod' }));
const hasChildren = vi.fn(async (_id: string) => false);
const restoreBranchFromParent = vi.fn(async (_dev: string, _parent: string) => ({
	operations: [{ id: 'op-1', action: 'restore', status: 'running', branchId: 'br-dev' }],
}));
const getOperation = vi.fn(async (id: string) => ({ id, action: 'restore', status: 'finished', branchId: 'br-dev' }));

vi.mock('#lib/server/db/index.ts', async () => {
	const { createTestDb } = await import('#lib/server/test/db.ts');
	const { db, client } = await createTestDb();
	testClient = client;
	return { db };
});

vi.mock('#lib/server/neon/index.ts', () => ({
	neonConfigured: () => neonConfigured(),
	resolveTargets: () => resolveTargets(),
	hasChildren: (id: string) => hasChildren(id),
	restoreBranchFromParent: (a: string, b: string) => restoreBranchFromParent(a, b),
	getOperation: (id: string) => getOperation(id),
	NEON_OP_TERMINAL_OK: 'finished',
	NEON_OP_TERMINAL_FAIL: ['failed', 'cancelled'],
}));

vi.mock('#lib/server/monitoring/index.ts', () => ({
	sanitizeError: (e: unknown) => (e instanceof Error ? e.message : String(e)),
}));

const { db } = await import('#lib/server/db/index.ts');
const { dbopsOperation } = await import('#lib/server/db/schema/dbops/operation.ts');
const { startOperation, advanceOperation } = await import('./operations');
const { ConflictError } = await import('./types');

const INPUT = {
	kind: 'reset_from_parent' as const,
	trigger: 'manual' as const,
	actorId: 'usr_1',
	actorEmail: 'admin@example.com',
};

beforeEach(async () => {
	vi.clearAllMocks();
	neonConfigured.mockReturnValue(true);
	resolveTargets.mockResolvedValue({ devBranchId: 'br-dev', parentBranchId: 'br-prod' });
	hasChildren.mockResolvedValue(false);
	restoreBranchFromParent.mockResolvedValue({
		operations: [{ id: 'op-1', action: 'restore', status: 'running', branchId: 'br-dev' }],
	});
	getOperation.mockImplementation(async (id: string) => ({
		id,
		action: 'restore',
		status: 'finished',
		branchId: 'br-dev',
	}));
	await db.delete(dbopsOperation);
});

afterAll(async () => {
	await testClient?.close();
});

describe('startOperation — concurrency lock', () => {
	it('blocks a second in-flight refresh with ConflictError (partial-unique index)', async () => {
		const first = await startOperation(INPUT);
		expect(first.operation.status).toBe('running');
		expect(first.replayed).toBe(false);

		await expect(startOperation(INPUT)).rejects.toBeInstanceOf(ConflictError);

		// The DB index is the real guard — exactly one row may exist.
		const rows = await db.select().from(dbopsOperation);
		expect(rows).toHaveLength(1);
	});

	it('frees the lock once the prior operation reaches a terminal state', async () => {
		const first = await startOperation(INPUT);
		await advanceOperation(first.operation.id); // op-1 finished → succeeded → leaves the active set

		const second = await startOperation(INPUT);
		expect(second.operation.status).toBe('running');
		expect(second.replayed).toBe(false);
	});
});

describe('startOperation — idempotency replay', () => {
	it('replays the original operation for a repeated key, without re-firing the Neon restore', async () => {
		const key = 'idem-abc';
		const a = await startOperation({ ...INPUT, idempotencyKey: key });
		expect(a.replayed).toBe(false);
		expect(restoreBranchFromParent).toHaveBeenCalledTimes(1);

		const b = await startOperation({ ...INPUT, idempotencyKey: key });
		expect(b.replayed).toBe(true);
		expect(b.operation.id).toBe(a.operation.id);
		expect(restoreBranchFromParent).toHaveBeenCalledTimes(1); // not fired again
	});
});

describe('advanceOperation — terminal idempotency', () => {
	it('transitions running → succeeded once, then no-ops (no re-poll, finishedAt frozen)', async () => {
		const { operation } = await startOperation(INPUT);
		getOperation.mockClear();

		const first = await advanceOperation(operation.id);
		expect(first?.status).toBe('succeeded');
		expect(first?.finishedAt).not.toBeNull();
		expect(getOperation).toHaveBeenCalledTimes(1);

		const second = await advanceOperation(operation.id);
		expect(second?.status).toBe('succeeded');
		expect(second?.finishedAt).toBe(first?.finishedAt); // unchanged
		expect(getOperation).toHaveBeenCalledTimes(1); // terminal operation is not re-polled
	});

	it('marks the operation failed when a Neon operation fails', async () => {
		const { operation } = await startOperation(INPUT);
		getOperation.mockResolvedValueOnce({ id: 'op-1', action: 'restore', status: 'failed', branchId: 'br-dev' });

		const advanced = await advanceOperation(operation.id);
		expect(advanced?.status).toBe('failed');
		expect(advanced?.error?.message).toBeTruthy();
	});
});

describe('PublicBranchOperation — no identifier leak (Finding A)', () => {
	it('exposes a non-identifying op count and omits raw branch / op ids', async () => {
		const { operation } = await startOperation(INPUT);
		expect(operation.neonOpCount).toBe(1);
		expect(operation).not.toHaveProperty('devBranchId');
		expect(operation).not.toHaveProperty('parentBranchId');
		expect(operation).not.toHaveProperty('neonOperationIds');
		expect(operation).not.toHaveProperty('neonOpStatuses');
	});
});

files.src/lib/server/dbops/operations.ts:
/**
 * dbops orchestrator — the single core called by the manual form action AND the
 * scheduled job. Executor model: lazy-advance-on-poll.
 *
 * `startOperation` fires the Neon restore (fast — returns operations[]) and
 * returns immediately with status `running`. `advanceOperation` (called from the
 * status endpoint on each poll, and from the scheduled job's drive loop) polls
 * the Neon operations and flips the operation to a terminal state. Lazy lease-expiry
 * in `advanceOperation` plus `reapExpiredOperations` recover crashed/abandoned operations.
 */
import { and, desc, eq, inArray, lt, or } from 'drizzle-orm';
import { createId } from '#lib/server/db/id.ts';
import { db } from '#lib/server/db/index.ts';
import { type DbopsOperation, dbopsOperation } from '#lib/server/db/schema/dbops/operation.ts';
import { sanitizeError } from '#lib/server/monitoring/index.ts';
import {
	getOperation,
	hasChildren,
	NEON_OP_TERMINAL_FAIL,
	NEON_OP_TERMINAL_OK,
	neonConfigured,
	resolveTargets,
	restoreBranchFromParent,
} from '#lib/server/neon/index.ts';
import {
	ConflictError,
	NotConfiguredError,
	type PublicBranchOperation,
	RefusedError,
	type StartOperationInput,
} from './types';

/** Generous lease — a copy-on-write reset is near-instant; this only guards crashes. */
const LEASE_MS = 5 * 60 * 1000;

function toPublicOperation(row: DbopsOperation): PublicBranchOperation {
	return {
		id: row.id,
		kind: row.kind,
		status: row.status,
		trigger: row.trigger,
		neonOpCount: row.neonOperationIds.length,
		error: row.error ?? null,
		actorEmail: row.actorEmail,
		createdAt: row.createdAt.toISOString(),
		updatedAt: row.updatedAt.toISOString(),
		finishedAt: row.finishedAt ? row.finishedAt.toISOString() : null,
	};
}

function isUniqueViolation(err: unknown): boolean {
	const e = err as { code?: string; cause?: { code?: string } };
	return e?.code === '23505' || e?.cause?.code === '23505';
}

function leaseUntil(): Date {
	return new Date(Date.now() + LEASE_MS);
}

export async function startOperation(
	input: StartOperationInput,
): Promise<{ operation: PublicBranchOperation; replayed: boolean }> {
	if (!neonConfigured()) throw new NotConfiguredError();

	// Idempotency replay — same key returns the original operation.
	if (input.idempotencyKey) {
		const [existing] = await db
			.select()
			.from(dbopsOperation)
			.where(eq(dbopsOperation.idempotencyKey, input.idempotencyKey))
			.limit(1);
		if (existing) return { operation: toPublicOperation(existing), replayed: true };
	}

	const targets = await resolveTargets(); // throws TargetsError if unconfigured

	// Reset-from-parent is rejected by Neon if the branch has children.
	if (await hasChildren(targets.devBranchId)) {
		throw new RefusedError('Dev branch has child branches; delete them before refreshing.');
	}

	// Insert as `running` — the active-unique index enforces one in-flight refresh.
	const id = createId.branchOperation();
	try {
		await db.insert(dbopsOperation).values({
			id,
			kind: input.kind,
			status: 'running',
			trigger: input.trigger,
			devBranchId: targets.devBranchId,
			parentBranchId: targets.parentBranchId,
			idempotencyKey: input.idempotencyKey ?? null,
			actorId: input.actorId,
			actorEmail: input.actorEmail,
			leaseExpiresAt: leaseUntil(),
		});
	} catch (err) {
		if (isUniqueViolation(err)) throw new ConflictError();
		throw err;
	}

	// Fire the Neon restore. Record op ids on success; mark failed on error.
	try {
		const { operations } = await restoreBranchFromParent(targets.devBranchId, targets.parentBranchId);
		const [updated] = await db
			.update(dbopsOperation)
			.set({
				neonOperationIds: operations.map((o) => o.id),
				neonOpStatuses: Object.fromEntries(operations.map((o) => [o.id, o.status])),
				leaseExpiresAt: leaseUntil(),
				updatedAt: new Date(),
			})
			.where(eq(dbopsOperation.id, id))
			.returning();
		return { operation: toPublicOperation(updated), replayed: false };
	} catch (err) {
		const [failed] = await db
			.update(dbopsOperation)
			.set({
				status: 'failed',
				error: { message: sanitizeError(err), at: new Date().toISOString() },
				finishedAt: new Date(),
				leaseExpiresAt: null,
				updatedAt: new Date(),
			})
			.where(eq(dbopsOperation.id, id))
			.returning();
		return { operation: toPublicOperation(failed), replayed: false };
	}
}

/** Advance an operation by polling its Neon operations. Idempotent; safe to call repeatedly. */
export async function advanceOperation(runId: string): Promise<PublicBranchOperation | null> {
	const [row] = await db.select().from(dbopsOperation).where(eq(dbopsOperation.id, runId)).limit(1);
	if (!row) return null;
	if (row.status !== 'running' && row.status !== 'queued') return toPublicOperation(row);

	// Lease lapsed → presumed crashed.
	if (row.leaseExpiresAt && row.leaseExpiresAt.getTime() < Date.now()) {
		const [failed] = await db
			.update(dbopsOperation)
			.set({
				status: 'failed',
				error: { message: 'operation lease expired', at: new Date().toISOString() },
				finishedAt: new Date(),
				leaseExpiresAt: null,
				updatedAt: new Date(),
			})
			.where(and(eq(dbopsOperation.id, runId), eq(dbopsOperation.status, 'running')))
			.returning();
		return toPublicOperation(failed ?? row);
	}

	if (row.neonOperationIds.length === 0) return toPublicOperation(row);

	try {
		const ops = await Promise.all(row.neonOperationIds.map((opId) => getOperation(opId)));
		const statuses = Object.fromEntries(ops.map((o) => [o.id, o.status]));
		const anyFailed = ops.some((o) => NEON_OP_TERMINAL_FAIL.includes(o.status));
		const allOk = ops.every((o) => o.status === NEON_OP_TERMINAL_OK);
		const guard = and(eq(dbopsOperation.id, runId), eq(dbopsOperation.status, 'running'));

		if (anyFailed) {
			const [failed] = await db
				.update(dbopsOperation)
				.set({
					status: 'failed',
					neonOpStatuses: statuses,
					error: { message: 'Neon operation failed', at: new Date().toISOString() },
					finishedAt: new Date(),
					leaseExpiresAt: null,
					updatedAt: new Date(),
				})
				.where(guard)
				.returning();
			return toPublicOperation(failed ?? row);
		}
		if (allOk) {
			const [done] = await db
				.update(dbopsOperation)
				.set({
					status: 'succeeded',
					neonOpStatuses: statuses,
					finishedAt: new Date(),
					leaseExpiresAt: null,
					updatedAt: new Date(),
				})
				.where(guard)
				.returning();
			return toPublicOperation(done ?? row);
		}
		const [still] = await db
			.update(dbopsOperation)
			.set({ neonOpStatuses: statuses, leaseExpiresAt: leaseUntil(), updatedAt: new Date() })
			.where(guard)
			.returning();
		return toPublicOperation(still ?? row);
	} catch {
		// Transient Neon error — leave running for the next poll.
		return toPublicOperation(row);
	}
}

export async function listOperations(
	limit: number,
	cursor: { createdAt: string; id: string } | null,
): Promise<PublicBranchOperation[]> {
	const rows = await db
		.select()
		.from(dbopsOperation)
		.where(
			cursor
				? or(
						lt(dbopsOperation.createdAt, new Date(cursor.createdAt)),
						and(eq(dbopsOperation.createdAt, new Date(cursor.createdAt)), lt(dbopsOperation.id, cursor.id)),
					)
				: undefined,
		)
		.orderBy(desc(dbopsOperation.createdAt), desc(dbopsOperation.id))
		.limit(limit + 1);
	return rows.map(toPublicOperation);
}

/** Best-effort cancel — marks the operation canceled and stops tracking. The Neon
 *  operation may still complete (Neon only cancels ops still scheduling). */
export async function cancelOperation(runId: string): Promise<PublicBranchOperation | null> {
	const [row] = await db.select().from(dbopsOperation).where(eq(dbopsOperation.id, runId)).limit(1);
	if (!row) return null;
	if (row.status !== 'running' && row.status !== 'queued') return toPublicOperation(row);
	const [canceled] = await db
		.update(dbopsOperation)
		.set({
			status: 'canceled',
			error: { message: 'canceled by operator', at: new Date().toISOString() },
			finishedAt: new Date(),
			leaseExpiresAt: null,
			updatedAt: new Date(),
		})
		.where(and(eq(dbopsOperation.id, runId), inArray(dbopsOperation.status, ['running', 'queued'])))
		.returning();
	return toPublicOperation(canceled ?? row);
}

/** Secondary reaper: fail operations whose lease lapsed (registered as a job). */
export async function reapExpiredOperations(): Promise<number> {
	const reaped = await db
		.update(dbopsOperation)
		.set({
			status: 'failed',
			error: { message: 'operation lease expired (reaped)', at: new Date().toISOString() },
			finishedAt: new Date(),
			leaseExpiresAt: null,
			updatedAt: new Date(),
		})
		.where(and(eq(dbopsOperation.status, 'running'), lt(dbopsOperation.leaseExpiresAt, new Date())))
		.returning({ id: dbopsOperation.id });
	return reaped.length;
}

/**
 * Schema-parity gate (invariant P3): every field of the client's
 * DockLayoutState must survive the server's valibot parse — `v.object`
 * strips unknown keys SILENTLY, so a field missing from
 * DockLayoutStateSchema silently diverges the DB workspace lane from
 * localStorage with no error anywhere.
 */

import * as v from 'valibot';
import { describe, expect, it } from 'vitest';
import type { DockLayoutState } from '#lib/components/desk/index.ts';
import { CreateWorkspaceSchema, SyncWorkspaceSchema } from './schemas';

const layout: Required<DockLayoutState> = {
	version: 1,
	root: { type: 'leaf', id: 'l1', tabs: ['p1'], activeTab: 'p1' },
	panels: { p1: { id: 'p1', type: 'editor', label: 'Editor' } },
	activityBarPosition: 'left',
	focusedLeafId: 'l1',
};

describe('DockLayoutState ↔ DockLayoutStateSchema parity', () => {
	it('CreateWorkspaceSchema round-trips every DockLayoutState field', () => {
		const parsed = v.safeParse(CreateWorkspaceSchema, { name: 'ws', layout });
		expect(parsed.success).toBe(true);
		if (!parsed.success) return;
		// Object.keys equality is the actual gate: a new client field that the
		// server schema lacks shows up here as a missing key, not silently.
		expect(Object.keys(parsed.output.layout).sort()).toEqual(Object.keys(layout).sort());
		expect(parsed.output.layout.focusedLeafId).toBe('l1');
	});

	it('SyncWorkspaceSchema preserves focusedLeafId in the save payload', () => {
		const parsed = v.safeParse(SyncWorkspaceSchema, { save: { id: 'ws1', layout }, activate: 'ws1' });
		expect(parsed.success).toBe(true);
		if (!parsed.success) return;
		expect(parsed.output.save?.layout.focusedLeafId).toBe('l1');
	});

	it('focusedLeafId stays optional (old persisted states load)', () => {
		const { focusedLeafId: _omitted, ...legacy } = layout;
		const parsed = v.safeParse(CreateWorkspaceSchema, { name: 'ws', layout: legacy });
		expect(parsed.success).toBe(true);
	});
});

