/**
 * Performance budgets and how to score a number against them.
 *
 * `budgets.json` is the single source of truth for two consumers that would
 * otherwise drift: this module (the observatory + the gate test) and the shell
 * probes in `scripts/perf/`. Neither may hardcode its own thresholds.
 *
 * Budgets carry a `kind` because the same metric name means different things in
 * the two measurement contexts, and conflating them produces false verdicts.
 * `ttfb_ms` (lab) is first-byte from a warm local preview, where 600 ms really is
 * a regression. `field_ttfb_ms` is p75 first-byte from real users on the far side
 * of the public internet, a serverless cold start and TLS — scoring that against
 * the lab budget reports a failure on every healthy deployment. The field bands
 * are Google's published Core Web Vitals thresholds so the verdict matches what
 * Search Console reports.
 */

import raw from './budgets.json';

export type BudgetKind = 'lab' | 'field';
export type BudgetVerdict = 'pass' | 'warn' | 'fail';

export interface Budget {
	/** Investigate at or above this value. */
	warn: number;
	/** Treat as a regression at or above this value. */
	fail: number;
	kind: BudgetKind;
	note: string;
}

export const budgets = raw.budgets as Readonly<Record<string, Budget>>;

export type BudgetKey = keyof typeof raw.budgets;

/**
 * The ratchet: the measured value at the moment it was accepted.
 *
 * Targets and ceilings are separate because they answer different questions. The
 * `route_js_kb` target is 250 KB and the heaviest route measures 511 — that gap
 * is a real, honest finding and it belongs on the dashboard. But a gate wired to
 * an aspirational target fails on the day it lands, and a gate that fails on day
 * one gets muted, after which it protects nothing.
 *
 * So the gate asserts against these instead. They stop the number growing while
 * the target stays visible as the thing still to fix. They move DOWN to bank an
 * improvement, and UP only as an explicit, reviewed decision once feature work has
 * used the headroom — never to absorb a dependency, which is what they exist to catch.
 */
export const ceilings = raw.ceilings as Readonly<Record<string, number>>;

/**
 * Score a measurement. Every budget here is "lower is better", so the comparison
 * is one-directional by construction — if a "higher is better" budget is ever
 * added this needs a direction field rather than a special case at the call site.
 *
 * Boundaries are inclusive of the threshold (`>=`) to match Google's wording:
 * LCP is "good" up to and including 2500 ms, so 2500 passes and 2501 warns.
 */
export function scoreBudget(key: BudgetKey, value: number): BudgetVerdict {
	const budget = budgets[key];
	if (!budget) throw new Error(`Unknown performance budget: ${key}`);
	if (value > budget.fail) return 'fail';
	if (value > budget.warn) return 'warn';
	return 'pass';
}

/** Web Vitals metric names as emitted by `web-vitals/attribution`. */
export const FIELD_METRICS = ['LCP', 'INP', 'CLS', 'FCP', 'TTFB'] as const;
export type FieldMetric = (typeof FIELD_METRICS)[number];

const FIELD_BUDGET_KEYS: Record<FieldMetric, BudgetKey> = {
	LCP: 'field_lcp_ms',
	INP: 'field_inp_ms',
	CLS: 'field_cls',
	FCP: 'field_fcp_ms',
	TTFB: 'field_ttfb_ms',
};

export function fieldBudgetKey(metric: string): BudgetKey | null {
	return FIELD_BUDGET_KEYS[metric as FieldMetric] ?? null;
}

/**
 * Below this many samples a p75 is not a p75 — it is one or two slow page loads
 * wearing a percentile's clothes. The observatory renders the number but marks
 * it provisional, because hiding it entirely is how a metric silently goes
 * unwatched for a month.
 *
 * 20 is a floor for readability, not a statistical guarantee: at n=20 a p75 is
 * still the 15th-ranked sample and moves a lot. It is the point below which the
 * number is actively misleading rather than merely noisy.
 */
export const MIN_SAMPLES_FOR_P75 = 20;

/** Is this sample count large enough for the percentile to mean anything? */
export function hasEnoughSamples(samples: number): boolean {
	return samples >= MIN_SAMPLES_FOR_P75;
}

/**
 * SCENARIO GATE — and the door the committed results are written through.
 *
 * The harness needs the application's module graph: it drives the real cache and
 * resilience modules, and those reach `$app/env/private`, which only Vite resolves.
 * That is why the runner is a test rather than a plain Bun script the way
 * `scripts/perf/snapshot.ts` is — `scripts/perf/scenarios.ts` spawns this file with
 * `PERF_WRITE_SCENARIOS=1`. A harness restricted to the modules that happen to avoid
 * `$app/env` would measure a convenient subset and call it the system.
 *
 * What is asserted is the deterministic half only: origin calls and the outcome string.
 * Latency is written to the file and never compared — on a shared CI host it measures
 * the host, and a gate that fails for that reason is a gate that gets muted.
 */
import { writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { beforeAll, describe, expect, it, vi } from 'vitest';
import { committedScenarios, compareScenarios, runScenarios, SCENARIO_IDS, type ScenarioRun } from './scenarios';

// No Redis, always. A lab measurement that depends on whether the developer happens to
// have Upstash credentials in their environment is two different measurements sharing
// a name — and every mechanism here has a defined in-process path without it.
vi.mock('#lib/server/cache/client.ts', () => ({ redis: null }));
vi.mock('#lib/server/platform/after-response.ts', () => ({ deferAfterResponse: vi.fn() }));

const OUT = join(process.cwd(), 'src', 'lib', 'server', 'perf', 'scenarios.json');
const WRITING = process.env.PERF_WRITE_SCENARIOS === '1';

let fresh: ScenarioRun;

describe('performance scenarios', () => {
	beforeAll(async () => {
		fresh = await runScenarios();
		if (WRITING) {
			writeFileSync(OUT, `${JSON.stringify(fresh, null, '\t')}\n`);
			console.log(`[scenarios] wrote ${fresh.results.length} results to ${OUT}`);
			for (const r of fresh.results) {
				console.log(`  ${r.id.padEnd(30)} ${String(r.originCalls).padStart(3)} origin  ${r.latencyMs}ms  ${r.outcome}`);
			}
		}
	});

	it('runs every declared scenario', () => {
		expect(fresh.results.map((r) => r.id)).toEqual([...SCENARIO_IDS]);
	});

	it('was measured without a shared cache tier', () => {
		expect(fresh.sharedTier).toBe(false);
	});

	it('has a committed result for every scenario', () => {
		// A scenario added and never committed would otherwise be compared against
		// nothing and pass forever. Skipped while writing: the import was resolved from
		// the file this run is replacing.
		if (WRITING) return;
		expect(committedScenarios.results.map((r) => r.id).sort()).toEqual([...SCENARIO_IDS].sort());
	});

	it('matches the committed deterministic columns', () => {
		if (WRITING) return;
		const drifted = compareScenarios(fresh).filter((d) => d.changed);

		expect(
			drifted,
			`Scenario behaviour changed:\n${drifted
				.map(
					(d) =>
						`  ${d.id}: committed ${d.committed ? `${d.committed.originCalls} origin / ${d.committed.outcome}` : '(absent)'} ` +
						`→ now ${d.fresh.originCalls} origin / ${d.fresh.outcome}`,
				)
				.join('\n')}\nIf the change is deliberate, re-record it: podman exec v10r bun run perf:scenarios`,
		).toEqual([]);
	});

	it('bounds a hanging dependency well below the time it would have taken', () => {
		// The one timing claim worth asserting, because it is an order of magnitude and
		// not a few milliseconds: the caller waits for the slice, not for the dependency.
		const slow = fresh.results.find((r) => r.id === 'slow-dependency');
		expect(slow?.outcome).toBe('deadline-exceeded');
		expect(slow?.latencyMs).toBeLessThan(200);
	});
});

files.src/lib/server/perf/scenarios.ts:
/**
 * The scenario harness — what the system does when conditions are not ideal.
 *
 * Localhost is fast, the cache is warm, the dependency answers, and nothing else is
 * running. Every number the observatory reports was taken under those conditions, which
 * is why they cannot answer the question that actually decides whether a system is fast
 * in production: what happens when one of those stops being true.
 *
 * Each scenario makes exactly one condition adverse, drives the REAL mechanism against
 * a simulated dependency, and reports two kinds of column:
 *
 *   Deterministic — origin calls and the outcome string. Same input, same value, every
 *   run, on any machine. These are asserted by `scenarios.gate.test.ts` against the
 *   committed results, so a behaviour change has to be a reviewed diff.
 *
 *   Reported — latency. It moves with the host, so gating it would be gating the CI
 *   runner's mood. It is committed anyway because the SHAPE is the finding: a slow
 *   dependency bounded at 60 ms instead of 400 is the whole claim, and a run where that
 *   stops being true is worth seeing in a diff even though no test can assert it.
 *
 * The harness runs with NO Redis on purpose (`sharedTier: false` in the results). A lab
 * measurement that depends on a network service's mood is not a lab measurement, and
 * every mechanism here has a defined in-process behaviour without it — which is itself
 * worth exercising, since that is what a preview deployment runs.
 *
 * Not everything in `docs/blueprint/velocity/measurement.md`'s scenario grid is covered.
 * Cold compute, slow network, large dataset and optimistic-mutation failure need a real
 * deployment, a real network and a browser respectively. The doc says which is which;
 * this file does not pretend the uncovered rows are green.
 */

import {
	cacheKey,
	clearLocalCache,
	coalesce,
	definePolicy,
	readTiered,
	redis,
	writeTiered,
} from '#lib/server/cache/index.ts';
import { DeadlineExceededError, startDeadline } from '#lib/server/http/deadline.ts';
import {
	DEFAULT_NEEDS_MS,
	DEFAULT_SHED_ABOVE,
	defineBreaker,
	defineBulkhead,
	defineShedder,
	ResilienceError,
	retryWithin,
} from '#lib/server/resilience/index.ts';
import raw from './scenarios.json';

export const SCENARIO_IDS = [
	'cold-cache',
	'warm-cache',
	'expiry-burst',
	'slow-dependency',
	'failing-dependency',
	'concurrent-load',
	'retry-after-transient-failure',
	'refusal-not-retried',
	'shed-under-pressure',
] as const;

export type ScenarioId = (typeof SCENARIO_IDS)[number];

export interface ScenarioResult {
	id: ScenarioId;
	/** The single thing made adverse. */
	condition: string;
	/** Calls that reached the simulated dependency. Deterministic. */
	originCalls: number;
	/** What the mechanism did. Deterministic — this is the assertion. */
	outcome: string;
	/** Wall clock, rounded to a millisecond. Reported, never asserted. */
	latencyMs: number;
}

export interface ScenarioRun {
	generatedAt: string;
	/** Whether a shared cache tier was reachable. Always false for a committed run — see the header. */
	sharedTier: boolean;
	results: ScenarioResult[];
}

/** One unit of simulated dependency work. Long enough to measure, short enough to run in a gate. */
const ORIGIN_MS = 20;
/** A dependency that has stopped answering, as opposed to one that is merely slow. */
const HANGING_MS = 400;
/** The slice a caller is willing to wait for one dependency call. */
const SLICE_MS = 60;

const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

/** A dependency that counts how often it was actually reached. */
function simulatedOrigin(costMs = ORIGIN_MS) {
	let calls = 0;
	return {
		get calls() {
			return calls;
		},
		async call<T>(value: T): Promise<T> {
			calls++;
			await sleep(costMs);
			return value;
		},
	};
}

async function measure(work: () => Promise<{ originCalls: number; outcome: string }>) {
	const from = performance.now();
	const { originCalls, outcome } = await work();
	return { originCalls, outcome, latencyMs: Math.round(performance.now() - from) };
}

const CACHE_POLICY = definePolicy({ namespace: 'scenario', ttl: 60, scope: 'shared' });

const SCENARIOS: Record<
	ScenarioId,
	{ condition: string; run: () => Promise<{ originCalls: number; outcome: string }> }
> = {
	'cold-cache': {
		condition: 'nothing cached — the first caller after a deploy',
		async run() {
			clearLocalCache();
			const origin = simulatedOrigin();
			const key = cacheKey(CACHE_POLICY, { id: 'cold' });

			const hit = await readTiered<string>(CACHE_POLICY, key);
			if (!hit) await writeTiered(CACHE_POLICY, key, await origin.call('value'));

			return { originCalls: origin.calls, outcome: hit ? 'unexpected-hit' : 'origin-miss' };
		},
	},

	'warm-cache': {
		condition: 'the same read, immediately after — the ordinary case',
		async run() {
			const origin = simulatedOrigin();
			const key = cacheKey(CACHE_POLICY, { id: 'cold' });

			// Deliberately reuses `cold-cache`'s key and does NOT clear the local tier:
			// "warm" is a fact about what the previous scenario left behind, and
			// re-seeding it here would measure a write, not a hit.
			const hit = await readTiered<string>(CACHE_POLICY, key);
			if (!hit) await origin.call('value');

			return { originCalls: origin.calls, outcome: hit ? `${hit.tier}-hit` : 'unexpected-miss' };
		},
	},

	'expiry-burst': {
		condition: '50 callers arrive on the same key the moment it expires',
		async run() {
			const origin = simulatedOrigin();
			const key = `scenario-burst-${crypto.randomUUID()}`;

			await Promise.all(Array.from({ length: 50 }, () => coalesce(key, () => origin.call('value'))));

			return { originCalls: origin.calls, outcome: `coalesced-50-to-${origin.calls}` };
		},
	},

	'slow-dependency': {
		condition: `a dependency that takes ${HANGING_MS}ms against a ${SLICE_MS}ms slice`,
		async run() {
			const origin = simulatedOrigin(HANGING_MS);
			const deadline = startDeadline(1_000);

			let outcome = 'unbounded';
			try {
				await deadline.child(SLICE_MS).run(() => origin.call('value'));
				outcome = 'returned-late';
			} catch (error) {
				// The point is not that it failed. It is that the caller got an answer at
				// SLICE_MS instead of waiting out a dependency that had already lost them.
				outcome = error instanceof DeadlineExceededError ? 'deadline-exceeded' : 'unexpected-error';
			}

			return { originCalls: origin.calls, outcome };
		},
	},

	'failing-dependency': {
		condition: '12 callers against a dependency that is down, breaker threshold 3',
		async run() {
			const breaker = defineBreaker({
				name: 'scenario',
				openForSeconds: 30,
				failureThreshold: 3,
				failureWindowSeconds: 30,
			});
			const subject = crypto.randomUUID();
			let calls = 0;

			for (let caller = 0; caller < 12; caller++) {
				if (await breaker.isOpen(subject)) continue;
				calls++;
				await breaker.recordFailure(subject);
			}

			return { originCalls: calls, outcome: `open-after-${calls}-of-12` };
		},
	},

	'concurrent-load': {
		condition: '20 simultaneous callers against a pool of 4 with room for 4 more',
		async run() {
			const bulkhead = defineBulkhead({ name: 'scenario', maxConcurrent: 4, maxQueued: 4 });
			const origin = simulatedOrigin();

			const settled = await Promise.allSettled(
				Array.from({ length: 20 }, () => bulkhead.run(() => origin.call('value'))),
			);
			const refused = settled.filter((s) => s.status === 'rejected').length;

			// Refusing beyond capacity is the behaviour under test. An unbounded queue
			// would admit all 20 and hand every one of them a latency nobody can state.
			return { originCalls: origin.calls, outcome: `admitted-${20 - refused}-refused-${refused}` };
		},
	},

	'retry-after-transient-failure': {
		condition: 'a dependency that fails twice, then answers',
		async run() {
			const deadline = startDeadline(1_000);
			let calls = 0;

			await retryWithin(deadline, { attempts: 4, baseDelayMs: 5, maxDelayMs: 20, attemptMaxMs: 200 }, async () => {
				calls++;
				if (calls < 3) throw new Error('transient');
				return 'value';
			});

			return { originCalls: calls, outcome: `succeeded-on-attempt-${calls}` };
		},
	},

	'refusal-not-retried': {
		condition: 'a dependency that refuses — a full bulkhead, not a failure',
		async run() {
			const deadline = startDeadline(1_000);
			let calls = 0;

			try {
				await retryWithin(deadline, { attempts: 5, baseDelayMs: 5, maxDelayMs: 20 }, async () => {
					calls++;
					throw new ResilienceError('bulkhead_full', 'no capacity');
				});
			} catch {
				// Expected. A refusal does not become a success by being asked again, and
				// retrying one is how a busy system is turned into an overloaded one.
			}

			return { originCalls: calls, outcome: `attempted-${calls}-of-5` };
		},
	},

	'shed-under-pressure': {
		condition: 'load at 0.6 with 30ms of budget left',
		async run() {
			const shedder = defineShedder({ name: 'scenario', shedAbove: DEFAULT_SHED_ABOVE, needsMs: DEFAULT_NEEDS_MS });
			// Chosen so both axes fire in one scenario: 0.6 is under the deferred load
			// threshold but over the background one, and 30ms is under what deferred work
			// needs to be worth starting. A single signal would only ever prove one rule.
			const signals = { load: 0.6, remainingMs: 30 };

			const verdicts = (['critical', 'deferred', 'background'] as const).map(
				(priority) => `${priority}:${shedder.admit(priority, signals).reason}`,
			);

			// No dependency is called at all — that IS the mechanism. Shedding is the only
			// Velocity pattern whose success looks like nothing happening.
			return { originCalls: 0, outcome: verdicts.join(' ') };
		},
	},
};

/** Run every scenario in declaration order. Order matters: `warm-cache` reads what `cold-cache` left. */
export async function runScenarios(): Promise<ScenarioRun> {
	const results: ScenarioResult[] = [];

	for (const id of SCENARIO_IDS) {
		const { condition, run } = SCENARIOS[id];
		results.push({ id, condition, ...(await measure(run)) });
	}

	return { generatedAt: new Date().toISOString(), sharedTier: redis !== null, results };
}

/**
 * The committed run — the accepted behaviour, in the same spirit as `snapshot.json`.
 *
 * Regenerate with `bun run perf:scenarios` after a deliberate change; the gate compares
 * a fresh run's deterministic columns against this and fails on any difference, so a
 * behaviour change arrives as a reviewed diff rather than as a number nobody noticed.
 */
export const committedScenarios = raw as ScenarioRun;

export interface ScenarioDrift {
	id: ScenarioId;
	/** null when the committed run does not contain this scenario at all. */
	committed: { originCalls: number; outcome: string } | null;
	fresh: { originCalls: number; outcome: string };
	changed: boolean;
}

/** Compare a fresh run's deterministic columns against the committed ones. */
export function compareScenarios(fresh: ScenarioRun, accepted: ScenarioRun = committedScenarios): ScenarioDrift[] {
	return fresh.results.map((result) => {
		const match = accepted.results.find((r) => r.id === result.id) ?? null;
		const committed = match ? { originCalls: match.originCalls, outcome: match.outcome } : null;
		const current = { originCalls: result.originCalls, outcome: result.outcome };
		return {
			id: result.id,
			committed,
			fresh: current,
			changed: !committed || committed.originCalls !== current.originCalls || committed.outcome !== current.outcome,
		};
	});
}

