		expect(row('A-1006')?.weight).toBe('ca. 2kg');
		const report = (op: string) => run.reports.find((r) => r.op === op);
		expect(report('normalize_gtin')?.unresolved).toEqual([{ line: 7, value: '4.01235E+12' }]);
