/**
 * The one place the app reads `ENCRYPTION_KEY` and `ENCRYPTION_KEY_PREVIOUS`.
 *
 * Everything sealed with the ring — AI provider API keys, name-check vendor secrets — is
 * only as recoverable as these values, and the database cannot protect its own key, so they
 * stay in deployment secrets and are threaded into `aes-gcm.ts` by the caller. Rotation is
 * a ring change, not a loss: the new key becomes `ENCRYPTION_KEY`, the old one moves to
 * `ENCRYPTION_KEY_PREVIOUS` (comma-separated for more than one), and the
 * `encryption-reseal` job moves every envelope onto the new key. Dropping a key from the
 * ring before that sweep finished makes the secrets still sealed under it `undecryptable`
 * (`docs/blueprint/security/key-ring.md`).
 *
 * Fail at boot, not at first use: outside `dev` the ring is validated at import, so a
 * misconfigured deployment cannot look healthy until the first encrypt. Mirrors
 * `abuse/config.ts`'s `assertProductionConfig`, including the `dev` gate — an env var can
 * arrive wrong in the direction that skips the check, a build-mode constant cannot.
 */
import { dev } from '$app/env';
import { ENCRYPTION_KEY, ENCRYPTION_KEY_PREVIOUS } from '$app/env/private';
import { type EncryptionKeyRing, parseKeyRing } from './aes-gcm';

function assertProductionConfig(): void {
	if (dev) return;
	parseKeyRing(ENCRYPTION_KEY, ENCRYPTION_KEY_PREVIOUS);
}
assertProductionConfig();

/** The validated key ring, or an `EncryptionError('invalid_key')` — never a placeholder. */
export function getEncryptionKeyRing(): EncryptionKeyRing {
	return parseKeyRing(ENCRYPTION_KEY, ENCRYPTION_KEY_PREVIOUS);
}

/**
 * The re-seal loop every table of envelopes shares: open each with the ring, seal the stale
 * ones under the current key, and swap them in only while the row still holds what was read.
 * The owning domain supplies the rows and the compare-and-swap write; this module never sees
 * a table.
 */
import { type EncryptionKeyRing, resealEnvelope } from './aes-gcm';

export interface StoredEnvelope<K> {
	key: K;
	envelope: string;
}

export interface ResealOutcome {
	/** Envelopes moved onto the current key. */
	resealed: number;
	/** Envelopes no key of the ring opens — a key left the ring before this sweep finished. */
	unreadable: number;
}

export async function resealEnvelopes<K>(
	rows: readonly StoredEnvelope<K>[],
	ring: EncryptionKeyRing,
	replace: (key: K, from: string, to: string) => Promise<boolean>,
): Promise<ResealOutcome> {
	const outcome: ResealOutcome = { resealed: 0, unreadable: 0 };
	for (const row of rows) {
		let next: string | null;
		try {
			next = await resealEnvelope(row.envelope, ring);
		} catch {
			outcome.unreadable += 1;
			continue;
		}
		// A false swap means an administrator saved a new secret meanwhile — sealed under the
		// current key already, so there is nothing left to move.
		if (next !== null && (await replace(row.key, row.envelope, next))) outcome.resealed += 1;
	}
	return outcome;
}

