/**
 * The adapter against a real socket. A `node:http` server on an ephemeral port plays the
 * service — including every way a real one can misbehave — so classification, bounds,
 * retry and redaction are proven over actual HTTP, not a mocked `fetch`.
 */
import http from 'node:http';
import type { AddressInfo } from 'node:net';
import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it, vi } from 'vitest';
import { startDeadline } from '#lib/server/http/deadline.ts';
import { callService, SERVICE_OPERATIONS } from './client';
import { MAX_RESPONSE_BYTES } from './config';
import { EVALUATION_PRESETS } from './presets';
import type { ServiceTarget } from './targets';

const TOKEN = 'client-test-credential-0123456789abcdef';

interface Received {
	method: string;
	url: string;
	headers: http.IncomingHttpHeaders;
	body: string;
}

type Responder = (request: Received, res: http.ServerResponse) => void;

let server: http.Server;
let target: ServiceTarget;
let responder: Responder;
let received: Received[] = [];

const json = (res: http.ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}) => {
	res.writeHead(status, { 'content-type': 'application/json', ...headers });
	res.end(JSON.stringify(body));
};

const LIVE = { status: 'live' };
const STATUS = {
	service: 'runtime-lab',
	release: '0.1.0',
	uptimeMs: 1234,
	operations: ['evaluate'],
	limits: { maxEvents: 64, maxAmountCents: 100_000_000, maxBodyBytes: 8192 },
};
const ACCEPTED = {
	outcome: 'accepted',
	steps: [{ index: 0, event: 'pay', from: 'placed', to: 'paid' }],
	finalState: 'paid',
	paidCents: 4990,
	refundedCents: 0,
};

beforeAll(async () => {
	server = http.createServer(async (req, res) => {
		const chunks: Buffer[] = [];
		for await (const chunk of req) chunks.push(chunk as Buffer);
		const request = {
			method: req.method ?? '',
			url: req.url ?? '',
			headers: req.headers,
			body: Buffer.concat(chunks).toString('utf8'),
		};
		received.push(request);
		responder(request, res);
	});
	await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve));
	const { port } = server.address() as AddressInfo;
	target = { id: 'local', origin: `http://127.0.0.1:${port}`, token: TOKEN };
});

afterAll(async () => {
	server.closeAllConnections();
	await new Promise<void>((resolve) => server.close(() => resolve()));
});

// Failures log one line each by design; keep the test output to the assertions.
beforeEach(() => {
	vi.spyOn(console, 'warn').mockImplementation(() => {});
});

afterEach(() => {
	received = [];
	vi.restoreAllMocks();
});

const deadline = (ms = 2_000) => ({ deadline: startDeadline(ms) });

describe('callService — success', () => {
	it('sends the credential only to authenticated operations', async () => {
		responder = (request, res) => json(res, 200, request.url === '/health/live' ? LIVE : STATUS);
		await callService(target, SERVICE_OPERATIONS.live, undefined, deadline());
		await callService(target, SERVICE_OPERATIONS.status, undefined, deadline());
		expect(received.map((r) => [r.url, r.headers.authorization])).toEqual([
			['/health/live', undefined],
			['/v1/status', `Bearer ${TOKEN}`],
		]);
	});

	it('sends a well-formed request id and replaces one the service would reject', async () => {
		responder = (_, res) => json(res, 200, LIVE);
		const kept = await callService(target, SERVICE_OPERATIONS.live, undefined, {
			...deadline(),
			requestId: 'req-fixed-1',
		});
		expect(kept).toMatchObject({ ok: true, data: LIVE, httpStatus: 200, requestId: 'req-fixed-1' });
		expect(received[0]).toMatchObject({ method: 'GET', url: '/health/live' });
		expect(received[0].headers['x-request-id']).toBe('req-fixed-1');

		for (const hostile of ['has space', 'a\r\nx-injected: 1', 'x'.repeat(65)]) {
			const call = await callService(target, SERVICE_OPERATIONS.live, undefined, { ...deadline(), requestId: hostile });
			expect(call.ok).toBe(true);
			expect(call.requestId).not.toBe(hostile);
			expect(received.at(-1)?.headers['x-request-id']).toBe(call.requestId);
		}
	});

	it('separates the service’s own time from the round trip', async () => {
		responder = (_, res) => json(res, 200, STATUS, { 'server-timing': 'app;dur=0.250' });
		const call = await callService(target, SERVICE_OPERATIONS.status, undefined, deadline());
		expect(call.ok).toBe(true);
		expect(call.timing.serviceMs).toBe(0.25);
		expect(call.timing.roundTripMs).toBeGreaterThan(0);
		expect(call.timing.clientMs).toBeGreaterThanOrEqual(0);
		expect(call.timing.attempts).toBe(1);
	});

	it('posts the validated request body as JSON', async () => {
		responder = (_, res) => json(res, 200, ACCEPTED);
		const call = await callService(
			target,
			SERVICE_OPERATIONS.evaluate,
			EVALUATION_PRESETS.fulfilled.request,
			deadline(),
		);
		expect(call.ok).toBe(true);
		expect(received[0].headers['content-type']).toBe('application/json');
		expect(JSON.parse(received[0].body)).toEqual(EVALUATION_PRESETS.fulfilled.request);
	});

	it('ignores fields the service adds later (tolerant reader)', async () => {
		responder = (_, res) => json(res, 200, { ...STATUS, region: 'frankfurt' });
		const call = await callService(target, SERVICE_OPERATIONS.status, undefined, deadline());
		expect(call.ok && call.data).toEqual(STATUS);
	});
});

describe('callService — refusals and failures', () => {
	it('refuses an invalid request before anything is sent', async () => {
		responder = (_, res) => json(res, 200, ACCEPTED);
		const call = await callService(target, SERVICE_OPERATIONS.evaluate, { totalCents: 0, events: [] }, deadline());
		expect(call).toMatchObject({ ok: false, kind: 'invalid_request', httpStatus: null });
		expect(received).toHaveLength(0);
	});

	it.each([
		[401, 'unauthorized'],
		[413, 'too_large'],
		[408, 'timed_out'],
		[404, 'service_error'],
		[500, 'service_error'],
		[503, 'service_error'],
	] as const)('classifies HTTP %i as %s, with a fixed message', async (status, kind) => {
		responder = (_, res) => json(res, status, { error: { code: 'x', message: 'upstream detail <script>' } });
		const call = await callService(target, SERVICE_OPERATIONS.status, undefined, deadline());
		expect(call).toMatchObject({ ok: false, kind, httpStatus: status });
		expect(!call.ok && call.message).not.toContain('upstream detail');
	});

	it('passes on the service’s validation message for a 400, bounded', async () => {
		responder = (_, res) =>
			json(res, 400, {
				error: { code: 'invalid_request', message: `/totalCents: must be positive${'!'.repeat(500)}` },
			});
		const call = await callService(
			target,
			SERVICE_OPERATIONS.evaluate,
			EVALUATION_PRESETS.fulfilled.request,
			deadline(),
		);
		expect(call).toMatchObject({ ok: false, kind: 'invalid_request', httpStatus: 400 });
		expect(!call.ok && call.message.startsWith('/totalCents: must be positive')).toBe(true);
		expect(!call.ok && call.message.length).toBeLessThanOrEqual(240);
	});

	it.each([
		['not JSON', (res: http.ServerResponse) => res.writeHead(200).end('<html>proxy error page</html>')],
		['the wrong shape', (res: http.ServerResponse) => json(res, 200, { status: 'up' })],
		['a renamed field', (res: http.ServerResponse) => json(res, 200, { ...STATUS, uptime_ms: 1, uptimeMs: undefined })],
		['oversized', (res: http.ServerResponse) => json(res, 200, { ...STATUS, pad: 'x'.repeat(MAX_RESPONSE_BYTES) })],
	])('rejects a 2xx answer that is %s as malformed_response', async (_, respond) => {
		responder = (_req, res) => respond(res);
		const call = await callService(target, SERVICE_OPERATIONS.status, undefined, deadline());
		expect(call).toMatchObject({ ok: false, kind: 'malformed_response', httpStatus: 200 });
	});

	it('does not follow a redirect with the credential attached', async () => {
		responder = (request, res) => {
			if (request.url === '/elsewhere') return json(res, 200, LIVE);
			res.writeHead(302, { location: '/elsewhere' }).end();
		};
		const call = await callService(target, SERVICE_OPERATIONS.live, undefined, deadline());
		expect(call).toMatchObject({ ok: false, kind: 'service_error', httpStatus: 302 });
		expect(received.map((r) => r.url)).toEqual(['/health/live']);
	});

	it('classifies an oversized error page by its status, not its size', async () => {
		responder = (_, res) => {
			res.writeHead(500, { 'content-type': 'text/html' });
			res.end('x'.repeat(MAX_RESPONSE_BYTES + 1));
		};
		const call = await callService(target, SERVICE_OPERATIONS.status, undefined, deadline());
		expect(call).toMatchObject({ ok: false, kind: 'service_error', httpStatus: 500 });
	});

	it('never retries once a response arrived — a body cut mid-stream is malformed, once', async () => {
		responder = (_, res) => {
			res.writeHead(200, { 'content-type': 'application/json', 'content-length': '500' });
			res.write('{"service":"order-');
			setTimeout(() => res.destroy(), 20);
		};
		const call = await callService(target, SERVICE_OPERATIONS.status, undefined, deadline());
		expect(call).toMatchObject({ ok: false, kind: 'malformed_response', httpStatus: 200 });
		expect(call.timing.attempts).toBe(1);
		expect(received).toHaveLength(1);
	});

	it('times out a slow service within the deadline and does not retry it', async () => {
		responder = (_, res) => {
			setTimeout(() => json(res, 200, LIVE), 1_000);
		};
		const started = performance.now();
		const call = await callService(target, SERVICE_OPERATIONS.live, undefined, deadline(150));
		expect(call).toMatchObject({ ok: false, kind: 'timed_out', httpStatus: null });
		expect(call.timing.attempts).toBe(1);
		expect(performance.now() - started).toBeLessThan(900);
	});

	it('classifies a refused connection as unreachable, retrying idempotent operations once', async () => {
		const closed = await closedPortTarget();
		const call = await callService(closed, SERVICE_OPERATIONS.status, undefined, deadline());
		expect(call).toMatchObject({ ok: false, kind: 'unreachable', httpStatus: null });
		expect(call.timing.attempts).toBe(2);
	});

	it('never retries an operation not declared idempotent', async () => {
		const closed = await closedPortTarget();
		const once = { ...SERVICE_OPERATIONS.evaluate, idempotent: false };
		const call = await callService(closed, once, EVALUATION_PRESETS.fulfilled.request, deadline());
		expect(call).toMatchObject({ ok: false, kind: 'unreachable' });
		expect(call.timing.attempts).toBe(1);
	});
});

describe('callService — secrets', () => {
	it('keeps the credential and origin out of results and log lines', async () => {
		const warn = vi.mocked(console.warn);
		const outcomes = [];
		for (const status of [200, 401, 500]) {
			responder = (_, res) => json(res, status, status === 200 ? STATUS : { error: { code: 'x', message: TOKEN } });
			outcomes.push(await callService(target, SERVICE_OPERATIONS.status, undefined, deadline()));
		}
		const closed = await closedPortTarget();
		outcomes.push(await callService(closed, SERVICE_OPERATIONS.status, undefined, deadline()));

		const surfaced = JSON.stringify(outcomes) + JSON.stringify(warn.mock.calls);
		expect(warn).toHaveBeenCalled();
		expect(surfaced).not.toContain(TOKEN);
		expect(surfaced).not.toContain(target.origin);
		// The transport-error path is the one most likely to echo an address.
		expect(surfaced).not.toContain(closed.origin);
		expect(surfaced).not.toContain('127.0.0.1');
	});
});

/** A target on a port that was open a moment ago and is now closed: connection refused. */
async function closedPortTarget(): Promise<ServiceTarget> {
	const probe = http.createServer();
	await new Promise<void>((resolve) => probe.listen(0, '127.0.0.1', resolve));
	const { port } = probe.address() as AddressInfo;
	await new Promise<void>((resolve) => probe.close(() => resolve()));
	return { id: 'local', origin: `http://127.0.0.1:${port}`, token: TOKEN };
}

/**
 * The service client — the one function every caller of the external service goes through.
 *
 * Framework-free: it takes a resolved target, an operation, an input and a deadline, and
 * returns a value. It never throws for anything the network or the service can do, so a
 * service that is down, slow, misconfigured or lying cannot become an exception in a page
 * that merely calls it. What it guarantees:
 *
 * - **Bounded** — every attempt runs inside the caller's `Deadline` (`http/deadline.ts`),
 *   and the response body is read with a byte budget (`http/body.ts`).
 * - **Validated both ways** — the request against the contract mirror before it is sent
 *   (when the operation has a request schema), the response before it is returned
 *   (`contract.ts`).
 * - **Classified** — exactly one `ServiceFailureKind` per failure, from the status code or
 *   the transport error, never from message text.
 * - **Retried only when safe** — once, only for operations declared idempotent, and only
 *   when no response arrived (`unreachable`). Once a response head has arrived nothing is
 *   retried: the service has the request. A timeout is never retried either — the request
 *   may have been processed, and on a waking host a retry only waits for the same cold start.
 * - **Least privilege** — the credential is sent only on operations that need it.
 * - **Correlated and timed** — `x-request-id` is sent (the service echoes and logs it),
 *   the round trip is measured, and the service's own `Server-Timing: app` is read so the
 *   caller can separate network cost from processing cost.
 * - **Quiet about secrets** — the credential is a header and nothing else: never logged,
 *   never in a result, never in a message. The origin is not logged either.
 *
 * Deliberately absent: options to override the credential or skip validation. A drill that
 * needs either builds a different target or operation (`lab.ts`) — the reference client
 * stays the thing to copy.
 */
import * as v from 'valibot';
import { readTextBounded } from '#lib/server/http/body.ts';
import type { Deadline } from '#lib/server/http/deadline.ts';
import { readServerTimingMetric } from '#lib/server/http/request-timing.ts';
import { retryWithin } from '#lib/server/resilience/index.ts';
import type {
	OrderEvaluation,
	OrderEvaluationRequest,
	ServiceCallTiming,
	ServiceFailureKind,
	ServiceLiveness,
	ServiceOperationName,
	ServiceStatus,
} from '#lib/showcases/external-service/types.ts';
import {
	MAX_RESPONSE_BYTES,
	MAX_SERVICE_MESSAGE_LENGTH,
	RETRY_ATTEMPTS,
	RETRY_BASE_DELAY_MS,
	RETRY_MAX_DELAY_MS,
} from './config';
import {
	ErrorEnvelopeSchema,
	EvaluateRequestSchema,
	EvaluateResponseSchema,
	LiveResponseSchema,
	StatusResponseSchema,
} from './contract';
import type { ServiceTarget } from './targets';

export interface ServiceOperation<Input, Output> {
	name: ServiceOperationName;
	method: 'GET' | 'POST';
	path: string;
	/** Sends the target's bearer credential. Public operations do not get it. */
	authenticated: boolean;
	/** Safe to repeat: the same request has the same effect however often it arrives. */
	idempotent: boolean;
	requestSchema: v.GenericSchema<Input> | null;
	responseSchema: v.GenericSchema<Output>;
}

/** The service's operations. Paths are fixed here; a caller cannot supply one. */
export const SERVICE_OPERATIONS = {
	live: {
		name: 'live',
		method: 'GET',
		path: '/health/live',
		authenticated: false,
		idempotent: true,
		requestSchema: null,
		responseSchema: LiveResponseSchema,
	} satisfies ServiceOperation<undefined, ServiceLiveness>,
	status: {
		name: 'status',
		method: 'GET',
		path: '/v1/status',
		authenticated: true,
		idempotent: true,
		requestSchema: null,
		responseSchema: StatusResponseSchema,
	} satisfies ServiceOperation<undefined, ServiceStatus>,
	evaluate: {
		name: 'evaluate',
		method: 'POST',
		path: '/v1/evaluate',
		authenticated: true,
		// A pure function of its input — the contract says so (`openapi.json`), so it is
		// declared idempotent even though it is a POST.
		idempotent: true,
		requestSchema: EvaluateRequestSchema,
		responseSchema: EvaluateResponseSchema,
	} satisfies ServiceOperation<OrderEvaluationRequest, OrderEvaluation>,
};

export type ServiceCall<T> =
	| { ok: true; data: T; httpStatus: number; requestId: string; timing: ServiceCallTiming }
	| {
			ok: false;
			kind: ServiceFailureKind;
			/** `null` when nothing answered, or the client refused to send. */
			httpStatus: number | null;
			message: string;
			requestId: string;
			timing: ServiceCallTiming;
	  };

export interface ServiceCallOptions {
	deadline: Deadline;
	fetch?: typeof fetch;
	/**
	 * Correlation id to send. Used only when it satisfies the service's own rule (1–64 of
	 * `[A-Za-z0-9._-]`) — otherwise the service would replace it and the id in our result
	 * would match no service log line; a fresh UUID is minted instead.
	 */
	requestId?: string;
}

/** No response arrived: refused, reset before a response, DNS. The one failure a retry can fix. */
class ServiceUnreachableError extends Error {
	constructor() {
		super('no response from the service');
		this.name = 'ServiceUnreachableError';
	}
}

const FAILURE_MESSAGES: Record<ServiceFailureKind, string> = {
	unreachable: 'Nothing answered at the configured address.',
	timed_out: 'No complete answer within the deadline.',
	unauthorized: 'The service refused the credential.',
	invalid_request: 'The service refused the request as invalid.',
	too_large: 'The request body exceeded the service limit.',
	service_error: 'The service answered with an unexpected error status.',
	malformed_response: 'The answer did not match the contract.',
};

/** The error statuses this client tells apart; every other non-2xx is `service_error`. */
export const CLASSIFIED_ERROR_STATUSES = {
	400: 'invalid_request',
	401: 'unauthorized',
	408: 'timed_out',
	413: 'too_large',
} as const;

function statusKind(status: number): ServiceFailureKind {
	return (CLASSIFIED_ERROR_STATUSES as Record<number, ServiceFailureKind>)[status] ?? 'service_error';
}

const REQUEST_ID_RULE = /^[A-Za-z0-9._-]{1,64}$/;

const round = (ms: number) => Math.round(ms * 100) / 100;

export async function callService<Input, Output>(
	target: ServiceTarget,
	operation: ServiceOperation<Input, Output>,
	input: Input,
	options: ServiceCallOptions,
): Promise<ServiceCall<Output>> {
	const started = performance.now();
	const requestId =
		options.requestId && REQUEST_ID_RULE.test(options.requestId) ? options.requestId : crypto.randomUUID();
	const fetchImpl = options.fetch ?? fetch;
	let attempts = 0;
	let roundTripMs: number | null = null;
	let serviceMs: number | null = null;

	const timing = (): ServiceCallTiming => {
		const totalMs = performance.now() - started;
		return {
			totalMs: round(totalMs),
			roundTripMs: roundTripMs === null ? null : round(roundTripMs),
			serviceMs: serviceMs === null ? null : round(serviceMs),
			clientMs: roundTripMs === null ? null : round(Math.max(0, totalMs - roundTripMs)),
			attempts,
		};
	};

	const fail = (kind: ServiceFailureKind, httpStatus: number | null, message?: string): ServiceCall<Output> => {
		const result = {
			ok: false as const,
			kind,
			httpStatus,
			message: message ?? FAILURE_MESSAGES[kind],
			requestId,
			timing: timing(),
		};
		// Operational facts only: no origin, no credential, no body.
		console.warn(
			`[external-service] ${operation.name} → ${kind}`,
			JSON.stringify({ target: target.id, httpStatus, requestId, ms: result.timing.totalMs, attempts }),
		);
		return result;
	};

	let body: string | undefined;
	if (operation.method === 'POST') {
		if (operation.requestSchema) {
			const parsed = v.safeParse(operation.requestSchema, input);
			if (!parsed.success) {
				const where = v.getDotPath(parsed.issues[0]) ?? 'request';
				return fail('invalid_request', null, `Rejected before sending: ${where} — ${parsed.issues[0].message}`);
			}
		}
		body = JSON.stringify(input);
	}

	const headers: Record<string, string> = { accept: 'application/json', 'x-request-id': requestId };
	if (operation.authenticated) headers.authorization = `Bearer ${target.token}`;
	if (body !== undefined) headers['content-type'] = 'application/json';

	let answered: { response: Response; text: string | null; cut: boolean };
	try {
		answered = await retryWithin(
			options.deadline,
			{
				attempts: operation.idempotent ? RETRY_ATTEMPTS : 1,
				baseDelayMs: RETRY_BASE_DELAY_MS,
				maxDelayMs: RETRY_MAX_DELAY_MS,
			},
			async (signal) => {
				attempts++;
				const attemptStarted = performance.now();
				let response: Response;
				try {
					response = await fetchImpl(new URL(operation.path, target.origin), {
						method: operation.method,
						headers,
						body,
						signal,
						// A fixed origin stays fixed: a redirect is an answer to classify, not a
						// destination to follow with the credential attached.
						redirect: 'manual',
					});
				} catch (error) {
					// An abort is the deadline speaking; anything else is "no response".
					if (signal.aborted) throw error;
					throw new ServiceUnreachableError();
				}
				// From here the service has the request: nothing below is retryable.
				let read: Awaited<ReturnType<typeof readTextBounded>> | null;
				try {
					read = await readTextBounded(response, MAX_RESPONSE_BYTES);
				} catch (error) {
					if (signal.aborted) throw error;
					read = null; // the connection died mid-body
				}
				roundTripMs = performance.now() - attemptStarted;
				serviceMs = readServerTimingMetric(response.headers.get('server-timing'), 'app');
				return { response, text: read?.ok ? read.value : null, cut: read === null };
			},
			{ retryable: (error) => error instanceof ServiceUnreachableError },
		);
	} catch (error) {
		return fail(error instanceof ServiceUnreachableError ? 'unreachable' : 'timed_out', null);
	}

	const { response, text, cut } = answered;

	if (!response.ok) {
		// The status decides, whatever the body did: an oversized or cut-off error page is
		// still that error.
		const kind = statusKind(response.status);
		let message: string | undefined;
		// The service's validation message names the offending field — worth passing on.
		// Every other kind keeps its fixed message: an error body is not trusted prose.
		if (kind === 'invalid_request' && text !== null) {
			const envelope = v.safeParse(ErrorEnvelopeSchema, parseJson(text));
			if (envelope.success) message = envelope.output.error.message.slice(0, MAX_SERVICE_MESSAGE_LENGTH);
		}
		return fail(kind, response.status, message);
	}

	if (cut) return fail('malformed_response', response.status, 'The answer was cut off.');
	if (text === null) {
		return fail('malformed_response', response.status, `The answer exceeded ${MAX_RESPONSE_BYTES} bytes.`);
	}
	const json = parseJson(text);
	if (json === undefined) return fail('malformed_response', response.status, 'The answer was not JSON.');
	const parsed = v.safeParse(operation.responseSchema, json);
	if (!parsed.success) {
		const where = v.getDotPath(parsed.issues[0]) ?? 'body';
		return fail('malformed_response', response.status, `The answer did not match the contract at ${where}.`);
	}

	return { ok: true, data: parsed.output, httpStatus: response.status, requestId, timing: timing() };
}

function parseJson(text: string): unknown {
	try {
		return JSON.parse(text);
	} catch {
		return undefined;
	}
}

