		surface: 'chatbot',
		risk: 'read',
		capability: 'project-docs',
		resultOrigin: 'system',
		reach: 'internal',
	},
	{
		name: 'search_pattern_library',
		surface: 'chatbot',
		risk: 'read',
		capability: 'pattern-library',
		resultOrigin: 'system',
		reach: 'internal',
	},
	// ── deskbot: scope-gated UI-parity tools ──
	{
		name: 'desk_list_files',
		surface: 'deskbot',
		risk: 'read',
		scope: 'desk:read',
		capability: 'desk-files',
		resultOrigin: 'user',
		reach: 'internal',
	},
	{
		name: 'desk_read_file',
		surface: 'deskbot',
		risk: 'read',
		scope: 'desk:read',
		capability: 'desk-files',
		resultOrigin: 'user',
		reach: 'internal',
	},
	{
		name: 'desk_file_tree',
		surface: 'deskbot',
		risk: 'read',
		scope: 'desk:read',
		capability: 'desk-files',
		resultOrigin: 'user',
		reach: 'internal',
	},
	{
		name: 'desk_search_files',
		surface: 'deskbot',
		risk: 'read',
		scope: 'desk:read',
		capability: 'desk-files',
		resultOrigin: 'user',
		reach: 'internal',
	},
	{
		name: 'desk_get_open_panels',
		surface: 'deskbot',
		risk: 'read',
		scope: 'desk:read',
		capability: 'desk-files',
		resultOrigin: 'user',
		reach: 'internal',
	},
	{
		name: 'desk_update_cells',
		surface: 'deskbot',
		risk: 'write',
		scope: 'desk:write',
		capability: 'desk-edit',
		resultOrigin: 'user',
		reach: 'internal',
	},
	{
		name: 'desk_rename_file',
		surface: 'deskbot',
		risk: 'write',
		scope: 'desk:write',
		capability: 'desk-edit',
		resultOrigin: 'user',
		reach: 'internal',
	},
	{
		name: 'desk_update_markdown',
		surface: 'deskbot',
		risk: 'write',
		scope: 'desk:write',
		capability: 'desk-edit',
		resultOrigin: 'user',
		reach: 'internal',
	},
	{
