import { beforeEach, describe, expect, it, vi } from 'vitest';

const { update, move, toggle } = vi.hoisted(() => ({ update: vi.fn(), move: vi.fn(), toggle: vi.fn() }));
vi.mock('#lib/server/db/desk/mutations.ts', () => ({
	updateSpreadsheetByFileId: update,
	moveFile: move,
	toggleFileAiContext: toggle,
	renameFile: vi.fn(),
	deleteFile: vi.fn(),
	duplicateSpreadsheetFile: vi.fn(),
}));
vi.mock('#lib/server/db/desk/queries.ts', () => ({
	getFile: vi.fn(),
	getMarkdownByFileId: vi.fn(),
	getSpreadsheetByFileId: vi.fn(),
}));
vi.mock('#lib/server/http/guards.ts', () => ({ guardApiUser: () => ({ user: { id: 'user' } }) }));
vi.mock('#lib/server/http/rate-limit.ts', () => ({
	createLimiter: () => ({ limit: async () => ({ success: true }) }),
	rateLimitResponse: vi.fn(),
}));

const { PUT } = await import('./+server');
const put = (body: unknown) =>
	PUT({
		params: { id: 'fil_test' },
		locals: {},
		request: new Request('https://example.test/api/desk/files/fil_test', {
			method: 'PUT',
			body: JSON.stringify(body),
		}),
	} as Parameters<typeof PUT>[0]);

beforeEach(() => vi.clearAllMocks());

describe('spreadsheet write HTTP contract', () => {
	it('requires a version before executing any mutations', async () => {
		const response = await put({ cells: {}, folderId: 'folder' });
		expect(response.status).toBe(400);
		expect(update).not.toHaveBeenCalled();
		expect(move).not.toHaveBeenCalled();
	});

	it('refuses mixed metadata operations rather than partially applying a conflicted request', async () => {
		const response = await put({ cells: {}, expectedVersion: 0, aiContext: true });
		expect(response.status).toBe(400);
		expect(update).not.toHaveBeenCalled();
		expect(toggle).not.toHaveBeenCalled();
	});

	it('returns an explicit 409 for stale versions', async () => {
		update.mockResolvedValueOnce({ status: 'conflict' });
		const response = await put({ cells: {}, expectedVersion: 2 });
		expect(response.status).toBe(409);
		expect(await response.json()).toMatchObject({ error: { code: 'version_conflict' } });
		expect(update).toHaveBeenCalledExactlyOnceWith('fil_test', 'user', { cells: {}, expectedVersion: 2 });
	});

	it('accepts the persisted cell shape and rejects a key the sheet cannot address', async () => {
		update.mockResolvedValueOnce({ status: 'saved', file: { id: 'fil_test' }, version: 1 });
		const cells = { A1: { v: 8, f: '=B1' }, B1: { v: 8 }, C1: { v: 'x', t: 'text' } };
		expect((await put({ cells, expectedVersion: 0 })).status).toBe(200);
		expect(update).toHaveBeenCalledExactlyOnceWith('fil_test', 'user', { cells, expectedVersion: 0 });

		expect((await put({ cells: { total: { v: 1 } }, expectedVersion: 0 })).status).toBe(400);
		expect((await put({ cells: { A1: { f: '=B1' } }, expectedVersion: 0 })).status).toBe(400);
		expect(update).toHaveBeenCalledOnce();
	});

	it('returns the new version for the next queued save', async () => {
		update.mockResolvedValueOnce({ status: 'saved', file: { id: 'fil_test' }, version: 3 });
		const response = await put({ cells: {}, expectedVersion: 2 });
		expect(response.status).toBe(200);
		expect(await response.json()).toEqual({ data: { file: { id: 'fil_test' }, version: 3 } });
	});
});

import * as v from 'valibot';
import { safeParse } from 'valibot';
import { checkDocumentLimit } from '#lib/server/db/retrieval/limits.ts';
import { MAX_AI_BODY_BYTES, payloadTooLargeResponse, readJsonBounded } from '#lib/server/http/body.ts';
import { guardApiUser } from '#lib/server/http/guards.ts';
import { createLimiter, rateLimitResponse } from '#lib/server/http/rate-limit.ts';
import { apiCreated, apiError, apiValidationError } from '#lib/server/http/response.ts';
import { INGEST_RATE_LIMIT_MAX, INGEST_RATE_LIMIT_WINDOW } from '#lib/server/retrieval/config.ts';
import { RetrievalError, retrievalErrorToStatus } from '#lib/server/retrieval/errors.ts';
import { ingest } from '#lib/server/retrieval/ingest/index.ts';
import type { RequestHandler } from './$types';

// Chunk + embed of up to 200k chars runs many sequential embedding calls; the
// serverless default (~10s) kills it mid-ingest on Vercel. Match the /stream sibling.
export const config = { runtime: 'nodejs22.x', maxDuration: 60 };

const ratelimit = createLimiter('rl:retrieval:ingest', INGEST_RATE_LIMIT_MAX, INGEST_RATE_LIMIT_WINDOW);

const IngestSchema = v.object({
	title: v.pipe(v.string(), v.minLength(1), v.maxLength(200)),
	content: v.pipe(v.string(), v.minLength(10), v.maxLength(200_000)),
	sourceType: v.optional(v.picklist(['upload', 'web', 'text', 'api'])),
	sourcePath: v.optional(v.string()),
});

export const POST: RequestHandler = async ({ request, locals }) => {
	const guard = guardApiUser(locals);
	if ('error' in guard) return guard.error;
	const { user } = guard;

	const { success, reset } = await ratelimit.limit(user.id);
	if (!success) return rateLimitResponse(reset);

	const read = await readJsonBounded(request, MAX_AI_BODY_BYTES);
	if (!read.ok) {
		if (read.reason === 'too_large') return payloadTooLargeResponse(MAX_AI_BODY_BYTES);
		return apiError(400, 'invalid_body', 'Invalid request body.');
	}
	const body = read.value;

	const parsed = safeParse(IngestSchema, body);
	if (!parsed.success) {
		return apiValidationError(parsed.issues);
	}

	const limitError = await checkDocumentLimit(user.id);
	if (limitError) {
		return apiError(403, 'limit_exceeded', limitError);
	}

	try {
		const result = await ingest({
			title: parsed.output.title,
			content: parsed.output.content,
			sourceType: parsed.output.sourceType ?? 'text',
			sourcePath: parsed.output.sourcePath,
			userId: user.id,
		});

		return apiCreated(result);
	} catch (err) {
		console.error('[api:retrieval:ingest] Error:', err instanceof Error ? err.message : err);
		if (err instanceof RetrievalError) {
			return apiError(retrievalErrorToStatus(err.kind), err.kind, err.message);
		}
		return apiError(500, 'ingestion_failed', 'Ingestion failed.');
	}
};

import * as v from 'valibot';
import { safeParse } from 'valibot';
import { MAX_AI_BODY_BYTES, payloadTooLargeResponse, readJsonBounded } from '#lib/server/http/body.ts';
import { guardApiUser } from '#lib/server/http/guards.ts';
